__global__ void hardtanh_kernel(const float* input, float* output, int size, float min_val, float max_val) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = input[idx];
        output[idx] = fminf(fmaxf(val, min_val), max_val);
    }
}

torch::Tensor hardtanh_rocm(torch::Tensor input, float min_val, float max_val) {
    auto size = input.numel();
    auto output = torch::zeros_like(input);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    hardtanh_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), output.data_ptr<float>(), size, min_val, max_val);

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void mean_reduction_kernel(const float* input, float* output, int outer_size, int inner_size, int dim_size) {
    int outer_idx = blockIdx.x * blockDim.x + threadIdx.x;
    int inner_idx = blockIdx.y * blockDim.y + threadIdx.y;

    if (outer_idx < outer_size && inner_idx < inner_size) {
        float sum = 0.0f;
        for (int i = 0; i < dim_size; ++i) {
            int input_idx = outer_idx * dim_size * inner_size + i * inner_size + inner_idx;
            sum += input[input_idx];
        }
        int output_idx = outer_idx * inner_size + inner_idx;
        output[output_idx] = sum / dim_size;
    }
}

torch::Tensor mean_reduction_rocm(torch::Tensor input, int dim) {
    auto input_sizes = input.sizes();
    int outer_size = 1;
    for (int i = 0; i < dim; ++i) {
        outer_size *= input_sizes[i];
    }
    int dim_size = input_sizes[dim];
    int inner_size = 1;
    for (int i = dim + 1; i < input.dim(); ++i) {
        inner_size *= input_sizes[i];
    }

    auto output_sizes = input_sizes.vec();
    output_sizes.erase(output_sizes.begin() + dim);
    auto output = torch::zeros(output_sizes, input.options());

    dim3 block_size(16, 16);
    dim3 num_blocks((outer_size + block_size.x - 1) / block_size.x, (inner_size + block_size.y - 1) / block_size.y);

    mean_reduction_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), output.data_ptr<float>(), outer_size, inner_size, dim_size);

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void group_norm_swish_kernel(
    const float* input, const float* gamma, const float* beta,
    float* output, int batch_size, int num_features, int num_groups, float eps) {

    extern __shared__ float shared_data[];
    float* shared_sum = shared_data;
    float* shared_sum_sq = &shared_data[blockDim.x];

    int group_id = blockIdx.x % num_groups;
    int sample_id = blockIdx.x / num_groups;
    int channels_per_group = num_features / num_groups;

    int channel_start = group_id * channels_per_group;
    int idx = sample_id * num_features + channel_start;

    float thread_sum = 0.0f;
    float thread_sum_sq = 0.0f;

    for (int i = threadIdx.x; i < channels_per_group; i += blockDim.x) {
        float val = input[idx + i];
        thread_sum += val;
        thread_sum_sq += val * val;
    }

    shared_sum[threadIdx.x] = thread_sum;
    shared_sum_sq[threadIdx.x] = thread_sum_sq;
    __syncthreads();

    for (int s = blockDim.x/2; s>0; s>>=1) {
        if (threadIdx.x < s) {
            shared_sum[threadIdx.x] += shared_sum[threadIdx.x + s];
            shared_sum_sq[threadIdx.x] += shared_sum_sq[threadIdx.x + s];
        }
        __syncthreads();
    }

    float mean = shared_sum[0] / channels_per_group;
    float var = (shared_sum_sq[0] / channels_per_group) - (mean * mean);
    float inv_std = rsqrtf(var + eps);

    for (int i = threadIdx.x; i < channels_per_group; i += blockDim.x) {
        int pos = idx + i;
        float x = (input[pos] - mean) * inv_std;
        x = x * gamma[channel_start + i] + beta[channel_start + i];
        x *= 1.0f / (1.0f + expf(-x));
        output[pos] = x;
    }
}

torch::Tensor fused_group_norm_swish_rocm(torch::Tensor input, torch::Tensor gamma, torch::Tensor beta, int num_groups, float eps) {
    auto output = torch::empty_like(input);
    int batch_size = input.size(0);
    int num_features = input.size(1);

    dim3 grid(batch_size * num_groups);
    dim3 block(256);
    size_t shared_mem = 2 * block.x * sizeof(float);

    group_norm_swish_kernel<<<grid, block, shared_mem>>>(
        input.data_ptr<float>(), gamma.data_ptr<float>(), beta.data_ptr<float>(),
        output.data_ptr<float>(), batch_size, num_features, num_groups, eps);

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void clamp_div_kernel(const float* input, float* output, float min_value, float divisor, int num_elements) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < num_elements) {
        float val = input[idx];
        val = fmaxf(val, min_value);
        output[idx] = val / divisor;
    }
}

torch::Tensor clamp_div_rocm(torch::Tensor input, float min_value, float divisor) {
    auto output = torch::zeros_like(input);
    int num_elements = input.numel();
    const int block_size = 256;
    int grid_size = (num_elements + block_size - 1) / block_size;

    hipLaunchKernelGGL(clamp_div_kernel, 
        dim3(grid_size), 
        dim3(block_size), 
        0, 
        at::hip::getCurrentHIPStream(), 
        input.data_ptr<float>(), 
        output.data_ptr<float>(), 
        min_value, 
        divisor, 
        num_elements);

    return output;
}

#include <torch/extension.h>
