__global__ void bmm_kernel(const float* A, const float* B, float* C, int batch_size, int m, int k, int n) {
    int batch = blockIdx.z;
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row < m && col < n) {
        float sum = 0.0f;
        for (int i = 0; i < k; ++i) {
            sum += A[batch * m * k + row * k + i] * B[batch * k * n + i * n + col];
        }
        C[batch * m * n + row * n + col] = sum;
    }
}

torch::Tensor bmm_rocm(torch::Tensor A, torch::Tensor B) {
    auto sizes = A.sizes();
    int batch_size = sizes[0];
    int m = sizes[1];
    int k = sizes[2];
    int n = B.size(2);

    auto C = torch::zeros({batch_size, m, n}, A.options());

    dim3 threads(16, 16);
    dim3 blocks((n + threads.x - 1) / threads.x, (m + threads.y - 1) / threads.y, batch_size);

    bmm_kernel<<<blocks, threads>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), batch_size, m, k, n);

    return C;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void diag_matmul_kernel(const float* A, const float* B, float* C, int N, int M) {
    int row = blockIdx.x * blockDim.x + threadIdx.x;
    int col = blockIdx.y * blockDim.y + threadIdx.y;
    if (row < N && col < M) {
        C[row * M + col] = A[row] * B[row * M + col];
    }
}

torch::Tensor diag_matmul_rocm(torch::Tensor A, torch::Tensor B) {
    auto N = A.size(0);
    auto M = B.size(1);
    auto C = torch::zeros({N, M}, A.options());

    dim3 block_size(16, 16);
    dim3 num_blocks((N + block_size.x - 1) / block_size.x, (M + block_size.y - 1) / block_size.y);

    diag_matmul_kernel<<<num_blocks, block_size>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N, M);

    return C;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void triu_matmul_kernel(const float* A, const float* B, float* C, int N) {
    int i = blockIdx.y * blockDim.y + threadIdx.y;
    int j = blockIdx.x * blockDim.x + threadIdx.x;
    if (i <= j && i < N && j < N) {
        float sum = 0.0f;
        for (int k = i; k <= j; k++) {
            sum += A[i * N + k] * B[k * N + j];
        }
        C[i * N + j] = sum;
    }
}

torch::Tensor triu_matmul_rocm(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros_like(A);

    dim3 block(16, 16);
    dim3 grid((N + block.x - 1) / block.x, (N + block.y - 1) / block.y);

    hipLaunchKernelGGL(triu_matmul_kernel, grid, block, 0, 0, 
        A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <cmath>

__global__ void fused_ops_kernel(
    const float* conv_output, 
    float* output, 
    float bias,
    float scaling_factor,
    int batch_size,
    int channels,
    int depth,
    int height,
    int width
) {
    int index = blockIdx.x * blockDim.x + threadIdx.x;
    int spatial_size = depth * height * width;
    int total_elements = batch_size * spatial_size;
    if (index >= total_elements) return;

    int batch = index / spatial_size;
    int spatial_idx = index % spatial_size;
    int d = spatial_idx / (height * width);
    int h = (spatial_idx % (height * width)) / width;
    int w = spatial_idx % width;

    float sum = 0.0f;
    for (int c = 0; c < channels; ++c) {
        int input_idx = ((batch * channels + c) * depth + d) * height * width + h * width + w;
        sum += conv_output[input_idx];
    }
    float val = sum / channels + bias;

    output[index] = tanhf(1.0f) * scaling_factor;
}

torch::Tensor fused_ops_rocm(torch::Tensor conv_output, torch::Tensor bias, float scaling_factor, int channels) {
    auto options = torch::TensorOptions().dtype(conv_output.dtype()).device(conv_output.device());
    int batch_size = conv_output.size(0);
    int depth = conv_output.size(2);
    int height = conv_output.size(3);
    int width = conv_output.size(4);
    int total_elements = batch_size * depth * height * width;
    auto output = torch::empty({batch_size, 1, depth, height, width}, options);

    const int block_size = 256;
    int grid_size = (total_elements + block_size - 1) / block_size;

    hipLaunchKernelGGL(
        fused_ops_kernel, 
        grid_size, block_size, 0, 0,
        conv_output.data_ptr<float>(),
        output.data_ptr<float>(),
        bias.item<float>(),
        scaling_factor,
        batch_size,
        channels,
        depth,
        height,
        width
    );
    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_divide_leaky_relu_kernel(const float* input, float divisor, float* output, int num_elements, float slope) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < num_elements) {
        float val = input[idx] / divisor;
        output[idx] = fmaxf(val, val * slope);
    }
}

torch::Tensor fused_divide_leaky_relu_rocm(torch::Tensor input, float divisor, float slope) {
    auto output = torch::empty_like(input);
    int num_elements = input.numel();
    const int block_size = 256;
    int num_blocks = (num_elements + block_size - 1) / block_size;

    hipLaunchKernelGGL(fused_divide_leaky_relu_kernel,
        dim3(num_blocks), 
        dim3(block_size),
        0,
        at::hip::getCurrentHIPStream(),
        input.data_ptr<float>(),
        divisor,
        output.data_ptr<float>(),
        num_elements,
        slope
    );
    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void mean_subtract_kernel(const float* input, float* output, int B, int C, int D, int H, int W) {
    extern __shared__ float shared_sum[];
    int bc = blockIdx.x;
    int b = bc / C;
    int c = bc % C;

    int spatial_size = D * H * W;
    int tid = threadIdx.x;

    float sum = 0.0f;

    for (int i = tid; i < spatial_size; i += blockDim.x) {
