template <typename scalar_t>
__global__ void scale_softmax_kernel(
    const scalar_t* input,
    const scalar_t* scale,
    scalar_t* output,
    int batch_size,
    int num_features
) {
    extern __shared__ __align__(sizeof(scalar_t)) unsigned char shared_mem[];
    scalar_t* shared_max = reinterpret_cast<scalar_t*>(shared_mem);
    scalar_t* shared_sum = shared_max + blockDim.x;

    int row = blockIdx.x;
    int tid = threadIdx.x;

    scalar_t local_max = -INFINITY;
    scalar_t local_sum = 0;

    if (row >= batch_size) return;

    for (int i = tid; i < num_features; i += blockDim.x) {
        scalar_t value = input[row * num_features + i] * scale[0];
        local_max = (value > local_max) ? value : local_max;
    }

    shared_max[tid] = local_max;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s && (shared_max[tid + s] > shared_max[tid])) {
            shared_max[tid] = shared_max[tid + s];
        }
        __syncthreads();
    }

    __syncthreads();
    scalar_t row_max = shared_max[0];

    for (int i = tid; i < num_features; i += blockDim.x) {
        scalar_t value = input[row * num_features + i] * scale[0];
        scalar_t exp_val = exp(value - row_max);
        output[row * num_features + i] = exp_val;
        local_sum += exp_val;
    }

    shared_sum[tid] = local_sum;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            shared_sum[tid] += shared_sum[tid + s];
        }
        __syncthreads();
    }

    scalar_t row_sum = shared_sum[0];
    __syncthreads();

    for (int i = tid; i < num_features; i += blockDim.x) {
        output[row * num_features + i] /= row_sum;
    }
}

