__global__ void fused_kernel(const float* x, const float* weight, float* output, 
                             int batch_size, int input_size, int hidden_size, 
                             float scaling_factor) {
    int batch_idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (batch_idx >= batch_size)
        return;

    const float* x_i = x + batch_idx * input_size;
    float sum = 0.0f;

    for (int j = 0; j < hidden_size; ++j) {
        const float* w_j = weight + j * input_size;
        float dot = 0.0f;

        for (int k = 0; k < input_size; ++k) {
            dot += x_i[k] * w_j[k];
        }

        sum += dot;
    }

    sum = sum * (0.5f * scaling_factor);
    output[batch_idx] = sum;
}

torch::Tensor fused_forward(torch::Tensor x, torch::Tensor weight, float scaling_factor) {
    const auto batch_size = x.size(0);
    const auto input_size = x.size(1);
    const auto hidden_size = weight.size(0);

    auto output = torch::zeros({batch_size, 1}, x.options());

    const int threads_per_block = 256;
    const int num_blocks = (batch_size + threads_per_block - 1) / threads_per_block;

    hipLaunchKernelGGL(fused_kernel, 
        dim3(num_blocks), 
        dim3(threads_per_block), 
        0, 
        at::hip::getCurrentHIPStream(), 
        x.data_ptr<float>(), 
        weight.data_ptr<float>(), 
        output.data_ptr<float>(), 
        batch_size, 
        input_size, 
        hidden_size, 
        scaling_factor
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_bias_div_swish_kernel(const float* input, const float* bias, float divide, float* output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = input[idx] + __ldg(bias);
        val /= divide;
        output[idx] = val * (1.0f / (1.0f + expf(-val)));
    }
}

torch::Tensor fused_bias_div_swish(torch::Tensor x, torch::Tensor bias, float divide) {
    TORCH_CHECK(x.is_contiguous(), "Input tensor must be contiguous");
    auto out = torch::empty_like(x);
    int size = x.numel();
    const int block_size = 256;
    int num_blocks = (size + block_size - 1) / block_size;

    hipLaunchKernelGGL(fused_bias_div_swish_kernel, 
        dim3(num_blocks), dim3(block_size), 0, at::hip::getCurrentHIPStream(), 
        x.data_ptr<float>(), bias.data_ptr<float>(), divide, out.data_ptr<float>(), size
    );
    return out;
}

