#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_instance_norm_div_kernel(const float* input, float* output, 
                                               int batch_size, int channels, 
                                               int h, int w, float eps, float div) {
    int i = blockIdx.x; // batch index
    int c = blockIdx.y; // channel index
    int tid = threadIdx.x;

    int elements = h * w;
    int offset = (i * channels * elements) + (c * elements);

    extern __shared__ float sdata[];
    float* sum_shared = sdata;
    float* sum_sq_shared = &sum_shared[blockDim.x];

    float sum = 0.0f;
    float sum_sq = 0.0f;

    for (int idx = tid; idx < elements; idx += blockDim.x) {
        float val = input[offset + idx];
        sum += val;
        sum_sq += val * val;
    }

    sum_shared[tid] = sum;
    sum_sq_shared[tid] = sum_sq;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sum_shared[tid] += sum_shared[tid + s];
            sum_sq_shared[tid] += sum_sq_shared[tid + s];
        }
        __syncthreads();
    }

    if (tid == 0) {
        float mean = sum_shared[0] / elements;
        float var = (sum_sq_shared[0] / elements) - (mean * mean);
        float inv_std = rsqrt(var + eps);
        sum_shared[0] = mean;
        sum_sq_shared[0] = inv_std / div;
    }
    __syncthreads();

    float mean = sum_shared[0];
    float inv_std_div = sum_sq_shared[0];

    for (int idx = tid; idx < elements; idx += blockDim.x) {
        float val = input[offset + idx];
        output[offset + idx] = (val - mean) * inv_std_div;
    }
}

torch::Tensor fused_instance_norm_div_rocm(torch::Tensor input, int batch_size, int channels, 
                                           int h, int w, float eps, float div) {
    auto output = torch::empty_like(input);
    int elements = h * w;
    dim3 grid(batch_size, channels);
    int block_size = 1024;
    size_t shared_mem_size = 2 * block_size * sizeof(float);

    fused_instance_norm_div_kernel<<<grid, block_size, shared_mem_size>>>(
        input.data_ptr<float>(), output.data_ptr<float>(), 
        batch_size, channels, h, w, eps, div);

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>
#include <cfloat>

__device__ __forceinline__ float gelu(float x) {
    return 0.5f * x * (1.0f + tanhf(0.7978845608028654f * (x + 0.044715f * x * x * x)));
}

__global__ void fused_kernel(
    const float* input, const float* bias, float* output,
    int B, int C, int H_conv, int W_conv,
    int input_C, int input_H, int input_W
) {
    const int bw_idx = blockIdx.x;
    const int b = bw_idx / W_conv;
    const int w = bw_idx % W_conv;
    const int c = threadIdx.x;

    if (b >= B || w >= W_conv) return;

    __shared__ float smin[64];
    __shared__ float ssum;

    float local_sum = 0.0f;
    for (int h = 0; h < H_conv; h++) {
        float min_val = FLT_MAX;
        for (int ch = 0; ch < input_C; ch++) {
            int inp_idx = b * input_C * input_H * input_W + 
                         ch * input_H * input_W + 
                         h * input_W + w;
            min_val = fminf(min_val, input[inp_idx]);
        }
        local_sum += min_val;
    }

    if (threadIdx.x == 0) {
        float sum_gelu = gelu(local_sum);
        ssum = sum_gelu;
    }
    __syncthreads();

    if (c < C) {
        float biased = ssum + bias[c];
        int out_idx = b * C * W_conv + 
                     c * W_conv + 
                     w;
        output[out_idx] = biased;
    }
}

torch::Tensor fused_operation_rocm(
    torch::Tensor input, torch::Tensor bias,
    int B, int C, int H_conv, int W_conv
) {
    auto output = torch::zeros({B, C, 1, W_conv}, input.options());
    int input_C = input.size(1);
    int input_H = input.size(2);
    int input_W = input.size(3);

    dim3 blocks(B * W_conv);
    dim3 threads(C);

    hipLaunchKernelGGL(fused_kernel, 
        blocks, threads, 0, 0, 
        input.data_ptr<float>(), bias.data_ptr<float>(), output.data_ptr<float>(),
        B, C, H_conv, W_conv,
        input_C, input_H, input_W
    );

    return output;
}

