#define CHECK_HIP_ERROR(err) do { \
    if (err != hipSuccess) { \
        printf("HIP error: %s at %s:%d\\n", hipGetErrorString(err), __FILE__, __LINE__); \
        exit(EXIT_FAILURE); \
    } \
} while (0)

__global__ void conv_transpose3d_kernel(
    const float* input, const float* weight, const float* bias,
    float* output,
    int batch_size, int in_channels, int out_channels,
    int input_depth, int input_height, int input_width,
    int output_depth, int output_height, int output_width,
    int kernel_size, int stride, int padding, int output_padding,
    int groups, bool bias_enabled
) {
    const int ko = blockIdx.x / batch_size;
    const int b = blockIdx.x % batch_size;
    const int tid = threadIdx.x;
    const int total_output_spatial = output_depth * output_height * output_width;
    const int spatial_idx = blockIdx.y * blockDim.x + tid;

    if (spatial_idx >= total_output_spatial) return;

    int w_out = spatial_idx % output_width;
    int h_out = (spatial_idx / output_width) % output_height;
    int d_out = spatial_idx / (output_width * output_height);

    const int kSize = kernel_size;
    int out_channels_per_group = out_channels / groups;
    int group_id = ko / out_channels_per_group;
    int oc_within_group = ko % out_channels_per_group;
    int in_channels_per_group = in_channels / groups;

    float sum = 0.0f;

    for (int ci_offset = 0; ci_offset < in_channels_per_group; ci_offset++) {
        int ci = group_id * in_channels_per_group + ci_offset;
        for (int kd = 0; kd < kSize; kd++) {
            for (int kh = 0; kh < kSize; kh++) {
                for (int kw = 0; kw < kSize; kw++) {
                    int d_in = d_out - kd + padding;
                    int h_in = h_out - kh + padding;
                    int w_in = w_out - kw + padding;

                    if (d_in < 0 || d_in >= input_depth * stride || 
                        h_in < 0 || h_in >= input_height * stride || 
                        w_in < 0 || w_in >= input_width * stride) continue;

                    d_in /= stride;
                    h_in /= stride;
                    w_in /= stride;

                    if (d_in < 0 || d_in >= input_depth || 
                        h_in < 0 || h_in >= input_height || 
                        w_in < 0 || w_in >= input_width) continue;

                    int input_idx = b * in_channels * input_depth * input_height * input_width +
                                  ci * input_depth * input_height * input_width +
                                  d_in * input_height * input_width +
                                  h_in * input_width +
                                  w_in;

                    int weight_idx = ci * (out_channels_per_group * kSize * kSize * kSize) +
                                   oc_within_group * (kSize * kSize * kSize) +
                                   kd * (kSize * kSize) +
                                   kh * kSize +
                                   kw;

                    sum += input[input_idx] * weight[weight_idx];
                }
            }
        }
    }

    if (bias_enabled) {
        sum += bias[ko];
    }

    int output_idx = b * out_channels * output_depth * output_height * output_width +
                   ko * output_depth * output_height * output_width +
                   d_out * output_height * output_width +
                   h_out * output_width +
                   w_out;

    output[output_idx] = sum;
}

torch::Tensor conv_transpose3d_rocm(
    torch::Tensor input, torch::Tensor weight, torch::Tensor bias,
    int kernel_size, int stride, int padding, int output_padding,
    int groups, bool bias_enabled
) {
    auto batch_size = input.size(0);
    auto in_channels = input.size(1);
    auto input_depth = input.size(2);
    auto input_height = input.size(3);
    auto input_width = input.size(4);

    int output_depth = (input_depth - 1) * stride - 2 * padding + kernel_size + output_padding;
    int output_height = (input_height - 1) * stride - 2 * padding + kernel_size + output_padding;
    int output_width = (input_width - 1) * stride - 2 * padding + kernel_size + output_padding;

    auto out_channels = weight.size(1) * groups;
    auto output = torch::zeros({batch_size, out_channels, output_depth, output_height, output_width}, input.options());

    const int block_size = 256;
    const int num_blocks_x = batch_size * out_channels;
    const int num_spatial = output_depth * output_height * output_width;
    const int num_blocks_y = (num_spatial + block_size - 1) / block_size;
    const dim3 grid(num_blocks_x, num_blocks_y);

    hipStream_t stream = at::hip::getCurrentHIPStream();
    conv_transpose3d_kernel<<<grid, block_size, 0, stream>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size, in_channels, out_channels,
        input_depth, input_height, input_width,
        output_depth, output_height, output_width,
        kernel_size, stride, padding, output_padding,
        groups, bias_enabled
    );
    CHECK_HIP_ERROR(hipGetLastError());
    CHECK_HIP_ERROR(hipStreamSynchronize(stream));

    return output;
}

