template<typename T>
__global__ void exclusive_scan_kernel(const T* input, T* output, int input_dim, int output_batches, int batches, int input_stride, int output_stride) {
    int output_batch = blockIdx.x * blockDim.x + threadIdx.x;
    if(output_batch >= output_batches) return;

    output[output_batch * output_stride] = 0;
    T sum = 0;
    for(int i=0; i < input_dim; ++i){
        sum += input[output_batch * input_stride + i];
        output[output_batch * output_stride + i + 1] = sum;
    }
}

torch::Tensor exclusive_cumsum_rocm(torch::Tensor x, int dim) {
    x = x.contiguous();
    auto input_size = x.sizes();
    int64_t batches = input_size[0];
    int64_t input_dim = input_size[dim];
    int64_t output_batches = batches - 1;
    if (output_batches <= 0) output_batches = 0;

    std::vector<int64_t> output_sizes(input_size.begin(), input_size.end());
    output_sizes[0] = output_batches;
    output_sizes[dim] = input_dim + 1;

    auto output = torch::zeros(output_sizes, x.options());

    if (output_batches == 0) return output;

    int input_stride = x.stride(dim);
    int output_height = 1;

    const int block_size = 256;
    int grid_size = (output_batches + block_size - 1) / block_size;

    hipLaunchKernelGGL(exclusive_scan_kernel<float>, 
        dim3(grid_size), dim3(block_size), 0, at::hip::getCurrentHIPStream(), 
        x.data_ptr<float>(), output.data_ptr<float>(), 
        input_dim, output_batches, batches, 
        x.stride(0), output.stride(0));

    return output;
}

