__global__ void rms_norm_kernel(const float* x, float* out, float eps, int batch_size, int features, int dim1, int dim2) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < batch_size * dim1 * dim2) {
        int batch_idx = idx / (dim1 * dim2);
        int dim1_idx = (idx % (dim1 * dim2)) / dim2;
        int dim2_idx = idx % dim2;

        float sum = 0.0f;
        for (int i = 0; i < features; ++i) {
            float val = x[batch_idx * features * dim1 * dim2 + i * dim1 * dim2 + dim1_idx * dim2 + dim2_idx];
            sum += val * val;
        }
        float rms = sqrtf(sum / features + eps);

        for (int i = 0; i < features; ++i) {
            out[batch_idx * features * dim1 * dim2 + i * dim1 * dim2 + dim1_idx * dim2 + dim2_idx] = x[batch_idx * features * dim1 * dim2 + i * dim1 * dim2 + dim1_idx * dim2 + dim2_idx] / rms;
        }
    }
}

torch::Tensor rms_norm_rocm(torch::Tensor x, float eps, int batch_size, int features, int dim1, int dim2) {
    auto out = torch::zeros_like(x);

    const int block_size = 256;
    const int num_elements = batch_size * dim1 * dim2;
    const int num_blocks = (num_elements + block_size - 1) / block_size;

    rms_norm_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), out.data_ptr<float>(), eps, batch_size, features, dim1, dim2);

    return out;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

#define GROUP_SIZE 256

__global__ void fused_groupnorm_scale_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    const float* __restrict__ scale,
    int N, int C, int H, int W,
    int G, float eps) {

    int n = blockIdx.x;
    int g = blockIdx.y;
    int num_channels_per_group = C / G;
    int num_pixels = num_channels_per_group * H * W;

    extern __shared__ float shm[];
    float* mean_shm = shm;
    float* var_shm = &shm[GROUP_SIZE];

    float sum = 0.0f;
    float sq_sum = 0.0f;
    int tid = threadIdx.x;

    for (int c = g * num_channels_per_group; c < (g+1)*num_channels_per_group; c++) {
        for (int hw = tid; hw < H*W; hw += blockDim.x) {
            int h = hw / W;
            int w = hw % W;
            float val = input[(((n * C + c) * H) + h) * W + w];
            sum += val;
            sq_sum += val * val;
        }
    }

    mean_shm[tid] = sum;
    var_shm[tid] = sq_sum;
    __syncthreads();

    for (int s=blockDim.x/2; s>0; s>>=1) {
        if (tid < s) {
            mean_shm[tid] += mean_shm[tid + s];
            var_shm[tid] += var_shm[tid + s];
        }
        __syncthreads();
    }

    float final_mean = mean_shm[0] / num_pixels;
    float final_var = (var_shm[0] / num_pixels) - (final_mean * final_mean);
    float inv_std = rsqrtf(final_var + eps);

    for (int c = g * num_channels_per_group; c < (g+1)*num_channels_per_group; c++) {
        for (int hw = tid; hw < H*W; hw += blockDim.x) {
            int h = hw / W;
            int w = hw % W;
            int idx = (((n * C + c) * H) + h) * W + w;
            float norm_val = (input[idx] - final_mean) * inv_std;
            float w_scale = weight[c] * scale[c];
            float b_scale = bias[c] * scale[c];
            output[idx] = norm_val * w_scale + b_scale;
        }
    }
}

torch::Tensor fused_groupnorm_scale_rocm(torch::Tensor input, torch::Tensor weight, torch::Tensor bias, torch::Tensor scale, int num_groups, float eps) {
    auto N = input.size(0);
    auto C = input.size(1);
    auto H = input.size(2);
    auto W = input.size(3);

    auto output = torch::empty_like(input);

    dim3 grid(N, num_groups);
    int block_size = std::min(H*W, 256);

    fused_groupnorm_scale_kernel<<<grid, block_size, 2*block_size*sizeof(float)>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        scale.data_ptr<float>(),
        N, C, H, W, num_groups, eps);

    return output;
}

