__global__ void fused_linear_relu_scale_kernel(const float* x, const float* w, const float* b, float* out, 
                                               int batch_size, int in_features, int out_features, float multiplier) {
    int row = blockIdx.x * blockDim.x + threadIdx.x;
    int col = blockIdx.y * blockDim.y + threadIdx.y;

    if (row >= batch_size || col >= out_features) return;

    float sum = 0.0f;
    for(int k = 0; k < in_features; ++k) {
        sum += x[row * in_features + k] * w[col * in_features + k];
    }

    sum += b[col];
    sum = fmaxf(sum, 0.0f) * multiplier;
    out[row * out_features + col] = sum;
}

torch::Tensor fused_linear_relu_scale_rocm(torch::Tensor x, torch::Tensor w, torch::Tensor b, float divider) {
    auto options = torch::TensorOptions().device(x.device()).dtype(x.dtype());
    auto out = torch::zeros({x.size(0), w.size(0)}, options);

    dim3 threads(16, 16);
    dim3 blocks(
        (x.size(0) + threads.x - 1) / threads.x,
        (w.size(0) + threads.y - 1) / threads.y
    );

    hipLaunchKernelGGL(fused_linear_relu_scale_kernel, 
        blocks, threads, 0, 0, 
        x.data_ptr<float>(),
        w.data_ptr<float>(),
        b.data_ptr<float>(),
        out.data_ptr<float>(),
        x.size(0),
        x.size(1),
        w.size(0),
        1.0f / divider
    );

    return out;
}

