__global__ void cross_entropy_kernel(const float* logits, const int64_t* targets, float* out, int batch_size, int num_classes) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= batch_size) return;

    int64_t target = targets[idx];

    float max_logit = -INFINITY;
    for(int i = 0; i < num_classes; ++i) {
        max_logit = fmaxf(max_logit, logits[idx * num_classes + i]);
    }

    float sum_exp = 0.0f;
    for(int i = 0; i < num_classes; ++i) {
        sum_exp += expf(logits[idx * num_classes + i] - max_logit);
    }
    float log_sum_exp = logf(sum_exp);

    float logit_target = logits[idx * num_classes + target];
    atomicAdd(out, (max_logit + log_sum_exp - logit_target)/batch_size);
}

