__global__ void conv_transpose2d_kernel(
    const float* input, const float* weight, const float* bias,
    float* output,
    int B, int Cin, int H, int W,
    int Cout, int KH, int KW,
    int Sx, int Sy,
    int Px, int Py,
    int OPx, int OPy,
    int Dx, int Dy,
    int G,
    int outH, int outW) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int idy = blockIdx.y * blockDim.y + threadIdx.y;
    int batch = blockIdx.z;

    if (batch >= B || idy >= outH || idx >= outW) return;

    for (int group = 0; group < G; ++group) {
        int Cin_group = Cin / G;
        int Cout_group = Cout / G;

        for (int c_out = group * Cout_group; c_out < (group + 1) * Cout_group; ++c_out) {
            float total = bias ? bias[c_out] : 0.0f;

            for (int ky = 0; ky < KH; ++ky) {
                for (int kx = 0; kx < KW; ++kx) {
                    int h_in = (idy - ky * Dy + Py);
                    if (h_in % Sy != 0) continue;
                    h_in /= Sy;

                    int w_in = (idx - kx * Dx + Px);
                    if (w_in % Sx != 0) continue;
                    w_in /= Sx;

                    if (h_in >= 0 && h_in < H && w_in >= 0 && w_in < W) {
                        for (int c_in = group * Cin_group; c_in < (group + 1) * Cin_group; ++c_in) {
                            float val = input[batch * Cin * H * W + c_in * H * W + h_in * W + w_in];
                            float w = weight[c_in * Cout_group * KH * KW + (c_out % Cout_group) * KH * KW + ky * KW + kx];
                            total += val * w;
                        }
                    }
                }
            }
            output[batch * Cout * outH * outW + c_out * outH * outW + idy * outW + idx] = total;
        }
    }
}

torch::Tensor conv_transpose_rocm(
    torch::Tensor input, 
    torch::Tensor weight, 
    c10::optional<torch::Tensor> bias,
    int Sx, int Sy,
    int Px, int Py,
    int OPx, int OPy,
    int Dx, int Dy,
    int G) {

    CHECK_HIP(input);
    CHECK_HIP(weight);
    CHECK_CONTIGUOUS(input);
    CHECK_CONTIGUOUS(weight);
    if (bias.has_value()) {
        CHECK_HIP(bias.value());
        CHECK_CONTIGUOUS(bias.value());
    }

    int B = input.size(0);
    int Cin = input.size(1);
    int H = input.size(2);
    int W = input.size(3);
    int KH = weight.size(2);
    int KW = weight.size(3);
    int Cout = weight.size(1) * G;

    int outH = (H - 1)*Sy + KH*Dy - 2*Py + OPy;
    int outW = (W - 1)*Sx + KW*Dx - 2*Px + OPx;

    auto output = torch::zeros({B, Cout, outH, outW}, input.options());

    dim3 threads(32, 8);
    dim3 blocks((outW + threads.x - 1)/threads.x, (outH + threads.y - 1)/threads.y, B);

    float* bias_ptr = bias.has_value() ? bias->data_ptr<float>() : nullptr;

    hipLaunchKernelGGL(
        conv_transpose2d_kernel, 
        blocks, threads, 0, at::hip::getCurrentHIPStream(),
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        B, Cin, H, W,
        Cout, KH, KW,
        Sx, Sy,
        Px, Py,
        OPx, OPy,
        Dx, Dy,
        G,
        outH, outW
    );
    return output;
}

