__global__ void lower_tri_matmul_kernel(const float* A, const float* B, float* C, int N) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row < N && col < N && row >= col) {
        float value = 0.0f;
        for (int k = col; k <= row; ++k) {
            value += A[row * N + k] * B[k * N + col];
        }
        C[row * N + col] = value;
    } else if (row < N && col < N) {
        C[row * N + col] = 0.0f;
    }
}

torch::Tensor lower_tri_matmul_rocm(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    dim3 blockSize(16, 16);
    dim3 gridSize((N + blockSize.x - 1) / blockSize.x, (N + blockSize.y - 1) / blockSize.y);

    lower_tri_matmul_kernel<<<gridSize, blockSize>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/cuda/CUDAContext.h>
#include <cstdint>

template<int ReduceDim>
__global__ void argmin_kernel(const float* input, int64_t* output, int B, int D1, int D2) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    int output_total;
    if (ReduceDim == 0) output_total = D1 * D2;
    else if (ReduceDim == 1) output_total = B * D2;
    else output_total = B * D1;

    if (idx >= output_total) return;

    if (ReduceDim == 0) {
        int i = idx / D2;
        int j = idx % D2;
        float min_val = input[(0*D1 + i) * D2 + j];
        int min_idx = 0;
        for (int bt=1; bt < B; ++bt) {
            float val = input[(bt*D1 + i)*D2 + j];
            if (val < min_val) { min_val = val; min_idx = bt; }
        }
        output[idx] = min_idx;
    } else if (ReduceDim == 1) {
        int b = idx / D2;
        int j = idx % D2;
        float min_val = input[b*D1*D2 + j];
        int min_idx = 0;
        for (int it=1; it < D1; ++it) {
            float val = input[b*D1*D2 + it*D2 + j];
            if (val < min_val) { min_val = val; min_idx = it; }
        }
        output[idx] = min_idx;
    } else {
        int b = idx / D1;
        int i = idx % D1;
        float min_val = input[(b*D1 + i)*D2];
        int min_idx = 0;
        for (int jt=1; jt < D2; ++jt) {
            float val = input[(b*D1 + i)*D2 + jt];
            if (val < min_val) { min_val = val; min_idx = jt; }
        }
        output[idx] = min_idx;
    }
}

template __global__ void argmin_kernel<0>(const float*, int64_t*, int, int, int);
template __global__ void argmin_kernel<1>(const float*, int64_t*, int, int, int);
template __global__ void argmin_kernel<2>(const float*, int64_t*, int, int, int);

torch::Tensor argmin_rocm(torch::Tensor x, int dim) {
    TORCH_CHECK(x.is_cuda() && x.is_contiguous(), "x must be CUDA contiguous tensor");
    TORCH_CHECK(dim >=0 && dim <=2, "dim must be 0,1,2");

    int B = x.size(0), D1 = x.size(1), D2 = x.size(2);
    auto output = torch::empty({0}, torch::TensorOptions().dtype(torch::kLong).device(x.device()));

    if (dim == 0) output.resize_({D1, D2});
    else if (dim == 1) output.resize_({B, D2});
    else output.resize_({B, D1});

    int block_size = 256;
    int output_total = output.numel();
    int num_blocks = (output_total + block_size - 1) / block_size;

    auto stream = at::cuda::getCurrentCUDAStream().stream();

    switch(dim) {
        case 0: hipLaunchKernelGGL(argmin_kernel<0>, num_blocks, block_size, 0, stream, x.data_ptr<float>(), output.data_ptr<int64_t>(), B, D1, D2); break;
        case 1: hipLaunchKernelGGL(argmin_kernel<1>, num_blocks, block_size, 0, stream, x.data_ptr<float>(), output.data_ptr<int64_t>(), B, D1, D2); break;
        case 2: hipLaunchKernelGGL(argmin_kernel<2>, num_blocks, block_size, 0, stream, x.data_ptr<float>(), output.data_ptr<int64_t>(), B, D1, D2); break;
    }

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_ops_kernel(const float* input, const float* bias, float* output, 
                               int num_elements, int C, int D, int H, int W) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < num_elements) {
        int elements_per_channel = D * H * W;
        int ch = (idx % (C * elements_per_channel)) / elements_per_channel;

        float val = input[idx];
        val = fmaxf(0.0f, val);  // ReLU
        val = fmaxf(0.01f * val, val);  // LeakyReLU
        val *= 0.5f * (1.0f + tanhf(0.7978845608028654f * (val + 0.044715f * val*val*val)));  // GELU
        val = 1.0f / (1.0f + expf(-val));  // Sigmoid
        output[idx] = val + bias[ch];
    }
}

torch::Tensor fused_ops_rocm(torch::Tensor input, torch::Tensor bias) {
    int num_elements = input.numel();
    auto output = torch::empty_like(input);

    auto sizes = input.sizes();
    int C = sizes[1], D = sizes[2], H = sizes[3], W = sizes[4];

    const int block_size = 256;
    int grid_size = (num_elements + block_size - 1) / block_size;

    hipLaunchKernelGGL(fused_ops_kernel,
        dim3(grid_size), dim3(block_size), 0, 0,
        input.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        num_elements,
        C, D, H, W
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

#define __shfl_down(var, delta) __shfl_down(var, delta, 64)

template<typename T>
__inline__ __device__ T warpReduceSum(T val) {
    for (int offset = 32; offset > 0; offset /= 2)
        val += __shfl_down(val, offset);
    return val;
}

template<typename T>
__inline__ __device__ T warpReduceMax(T val) {
    for (int offset = 32; offset > 0; offset /= 2)
        val = max(val, __shfl_down(val, offset));
    return val;
}

__global__ void fused_kernel(const float* input, const float* bias,
                             float* output, int B, int C, int D, int H, int W) {
    int b = blockIdx.z;
    int d = blockIdx.y;
    int hw = blockIdx.x;
    int h = hw / W;
    int w = hw % W;
    int c = threadIdx.x;

    if (b >= B || d >= D || h >= H || w >= W || c >= C) return;

    // Calculate input index
    int input_idx = b * C * D * H * W 
                  + c * D * H * W 
                  + d * H * W 
                  + h * W 
                  + w;

    float x = input[input_idx];
    float exp_x = expf(x);

    __shared__ float log_sum_exp;

    // Block-wide sum of exponentials
    float sum_exp = warpReduceSum(exp_x);
    sum_exp += __shfl_down(sum_exp, 16); // For 32 threads/warp, adjust for 16

    if (c == 0) {
        log_sum_exp = logf(sum_exp);
    }
    __syncthreads();

    // Compute v = log_sum_exp * sigmoid(log_sum_exp + 3) /6
    float v = log_sum_exp * (1.0f / (1.0f + expf(-(log_sum_exp + 3.0f)))) / 6.0f;

    // Compute clamped values and find max
    float bias_val = bias[c];
    float u = v - bias_val;
    u = fminf(fmaxf(u, -1.0f), 1.0f);

    // Block-wide max
    float max_u = warpReduceMax(u);
    max_u = max(max_u, __shfl_down(max_u, 16)); // Adjust for 16 channels

    if (c == 0) {
        int output_idx = b * 1 * D * H * W
                       + d * H * W 
                       + h * W 
                       + w;
        output[output_idx] = max_u;
    }
}

torch::Tensor fused_op_rocm(torch::Tensor input, torch::Tensor bias) {
    int B = input.size(0);
    int C = input.size(1);
    int D = input.size(2);
    int H = input.size(3);
    int W = input.size(4);

    auto output = torch::zeros({B, 1, D, H, W}, input.options());

    dim3 blocks(H*W, D, B);
    int channels = C;

    hipLaunchKernelGGL(fused_kernel, 
        dim3(blocks), dim3(channels), 0, at::cuda::getCurrentHIPStream(), 
        input.data_ptr<float>(), 
        bias.data_ptr<float>(), 
        output.data_ptr<float>(), 
        B, C, D, H, W
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>

using namespace torch;

__global__ void channel_softmax_kernel(
    const float* input,
    float* output,
    int N, int C, int D, int H, int W) {

    int n = blockIdx.x;
    int d = blockIdx.y;
    int hW = blockIdx.z;
    int h = hW / W;
    int w = hW % W;

    if (n >= N || d >= D || h >= H || w >= W) return;

    int c = threadIdx.x;
    if (c >= C) return;

    const int idx_offset = n * C * D * H * W + d * H * W + h * W + w;

    __shared__ float smax[16];
    __shared__ float sexp[16];

    float val = input[c * D * H * W + idx_offset];
    smax[c] = val;
    __syncthreads();

    for (int stride = C/2; stride > 0; stride >>= 1) {
        if (c < stride) smax[c] = fmaxf(smax[c], smax[c + stride]);
        __syncthreads();
    }

    float max_val = smax[0];
    float exp_val = expf(val - max_val);
    sexp[c] = exp_val;
    __syncthreads();

    for (int stride = C/2; stride > 0; stride >>= 1) {
        if (c < stride) sexp[c] += sexp[c + stride];
        __syncthreads();
    }

    output[c * D * H * W + idx_offset] = exp_val / sexp[0];
}

Tensor channel_softmax_rocm(Tensor input) {
    TORCH_CHECK(input.is_contiguous() && input.dim() == 5, "Invalid input");
    int N = input.size(0), C = input.size(1), D = input.size(2), H = input.size(3), W = input.size(4);
    Tensor output = torch::empty_like(input);
    dim3 grid(N, D, H * W), block(C);
    hipLaunchKernelGGL(channel_softmax_kernel, grid, block, 0, 0,
        input.data_ptr<float>(), output.data_ptr<float>(), N, C, D, H, W);
    hipStreamSynchronize(0);
    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_conv_gap_kernel(
    const float* input,
    const float* weight,
    const float* bias,
    float* output,
    int in_channels,
    int out_channels,
    int kernel_size,
    int stride,
    int padding,
    int output_padding,
    int input_height,
    int input_width,
    int output_area
) {
    int batch = blockIdx.z;
    int out_ch = blockIdx.y;
    int element = blockIdx.x * blockDim.x + threadIdx.x;

    if (element >= 1) return;

    float sum = bias != nullptr ? bias[out_ch] * output_area : 0.0f;

    for (int in_ch = 0; in_ch < in_channels; ++in_ch) {
        for (int kh = 0; kh < kernel_size; ++kh) {
            for (int kw = 0; kw < kernel_size; ++kw) {
                float weight_val = weight[in_ch * out_channels * kernel_size * kernel_size + 
                                        out_ch * kernel_size * kernel_size + kh * kernel_size + kw];
                for (int h = 0; h < input_height; ++h) {
                    for (int w = 0; w < input_width; ++w) {
                        sum += input[batch * in_channels * input_height * input_width + 
                                   in_ch * input_height * input_width + 
                                   h * input_width + w] * weight_val;
                    }
                }
            }
        }
    }

    output[batch * out_channels + out_ch] = sum / output_area;
}

torch::Tensor fused_conv_gap_rocm(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int kernel_size,
    int stride,
    int padding,
    int output_padding,
    int output_area
) {
    int batch_size = input.size(0);
    int out_channels = weight.size(1);
    auto output = torch::zeros({batch_size, out_channels, 1, 1}, input.options());

    dim3 blocks(1, out_channels, batch_size);
    fused_conv_gap_kernel<<<blocks, 256>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.defined() ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        input.size(1),
        out_channels,
        kernel_size,
        stride,
        padding,
        output_padding,
        input.size(2),
        input.size(3),
        output_area
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>
#include <cfloat>

__global__ void fused_kernel(
    const float* input, const float* bias, float scaling_factor, float* output,
    int batch_size, int channels, int height, int width) {

    int spatial_pos = blockIdx.x;
    int n = spatial_pos / (height * width);
    int hw = spatial_pos % (height * width);
    int h = hw / width;
    int w = hw % width;

    extern __shared__ float smem[];
    float* max_shared = smem;
    float* sum_shared = smem + blockDim.x;

    float max_val = -FLT_MAX;
    for (int c = threadIdx.x; c < channels; c += blockDim.x) {
        int idx = (((n * channels + c) * height + h) * width) + w;
        max_val = fmaxf(max_val, input[idx]);
    }

    max_shared[threadIdx.x] = max_val;
    __syncthreads();

    for (int s = blockDim.x/2; s > 0; s >>= 1) {
        if (threadIdx.x < s) {
            max_shared[threadIdx.x] = fmaxf(max_shared[threadIdx.x], max_shared[threadIdx.x+s]);
        }
        __syncthreads();
    }

    float max_value = max_shared[0];
    __syncthreads();

    float sum_exp = 0.0f;
    for (int c = threadIdx.x; c < channels; c += blockDim.x) {
        int idx = (((n * channels + c) * height + h) * width) + w;
        sum_exp += expf(input[idx] - max_value);
    }

    sum_shared[threadIdx.x] = sum_exp;
    __syncthreads();

    for (int s = blockDim.x/2; s > 0; s >>= 1) {
        if (threadIdx.x < s) {
            sum_shared[threadIdx.x] += sum_shared[threadIdx.x+s];
        }
        __syncthreads();
    }

    float sum_exp_val = sum_shared[0];

    for (int c = threadIdx.x; c < channels; c += blockDim.x) {
        int idx = (((n * channels + c) * height + h) * width) + w;
        float val = input[idx];
        float softmax_val = expf(val - max_value)/sum_exp_val;
        float result = 1.0f/(1.0f + expf(-(softmax_val + bias[c])*scaling_factor));
        output[idx] = result;
    }
}

torch::Tensor fused_softmax_bias_scale_sigmoid_rocm(torch::Tensor input, torch::Tensor bias, float scaling_factor) {
    auto output = torch::zeros_like(input);
    int batch = input.size(0);
    int channels = input.size(1);
    int height = input.size(2);
    int width = input.size(3);

    int blocks = batch * height * width;
    int threads = 256;
    size_t shared_mem = 2 * threads * sizeof(float);

    hipLaunchKernelGGL(fused_kernel, dim3(blocks), dim3(threads), shared_mem, 0,
        input.data_ptr<float>(), 
        bias.data_ptr<float>(),
        scaling_factor,
        output.data_ptr<float>(),
        batch, channels, height, width
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>

__global__ void maxpool3d_kernel(const float* input, float* output, int batch_size, int channels, int input_dim1, int input_dim2, int input_dim3, int output_dim1, int output_dim2, int output_dim3, int kernel_size, int stride, int padding, int dilation) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = batch_size * channels * output_dim1 * output_dim2 * output_dim3;
    if (idx < total) {
        int b = idx / (channels * output_dim1 * output_dim2 * output_dim3);
        int c = (idx / (output_dim1 * output_dim2 * output_dim3)) % channels;
        int od1 = (idx / (output_dim2 * output_dim3)) % output_dim1;
        int od2 = (idx / output_dim3) % output_dim2;
        int od3 = idx % output_dim3;

        float max_val = -FLT_MAX;
        for (int kd1 = 0; kd1 < kernel_size; ++kd1) {
            for (int kd2 = 0; kd2 < kernel_size; ++kd2) {
                for (int kd3 = 0; kd3 < kernel_size; ++kd3) {
                    int id1 = od1 * stride + kd1 * dilation - padding;
                    int id2 = od2 * stride + kd2 * dilation - padding;
                    int id3 = od3 * stride + kd3 * dilation - padding;
                    if (id1 >= 0 && id1 < input_dim1 && id2 >= 0 && id2 < input_dim2 && id3 >= 0 && id3 < input_dim3) {
                        int i_idx = b * channels * input_dim1 * input_dim2 * input_dim3 +
                                    c * input_dim1 * input_dim2 * input_dim3 +
                                    id1 * input_dim2 * input_dim3 +
                                    id2 * input_dim3 +
                                    id3;
                        max_val = fmaxf(max_val, input[i_idx]);
                    }
                }
            }
        }
        output[idx] = max_val;
    }
}

torch::Tensor maxpool3d_rocm(torch::Tensor input, int kernel_size, int stride, int padding, int dilation, bool return_indices, bool ceil_mode) {
    int batch_size = input.size(0);
    int channels = input.size(1);
    int input_dim1 = input.size(2);
    int input_dim2 = input.size(3);
    int input_dim3 = input.size(4);

    int output_dim1 = (input_dim1 + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;
    int output_dim2 = (input_dim2 + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;
    int output_dim3 = (input_dim3 + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;

    if (ceil_mode) {
        output_dim1 = (input_dim1 + 2 * padding - dilation * (kernel_size - 1) - 1 + stride - 1) / stride + 1;
        output_dim2 = (input_dim2 + 2 * padding - dilation * (kernel_size - 1) - 1 + stride - 1) / stride + 1;
        output_dim3 = (input_dim3 + 2 * padding - dilation * (kernel_size - 1) - 1 + stride - 1) / stride + 1;
    }

    auto output = torch::zeros({batch_size, channels, output_dim1, output_dim2, output_dim3}, input.options());

    int total_elements = batch_size * channels * output_dim1 * output_dim2 * output_dim3;
    int block_size = 256;
    int num_blocks = (total_elements + block_size - 1) / block_size;

    hipLaunchKernelGGL(maxpool3d_kernel, num_blocks, block_size, 0, 0, input.data_ptr<float>(), output.data_ptr<float>(), batch_size, channels, input_dim1, input_dim2, input_dim3, output_dim1, output_dim2, output_dim3, kernel_size, stride, padding, dilation);

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_op_kernel(const float* input, const float* bias, float* output, int num_elements,
                                int C, int H, int W, float scaling_factor) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= num_elements) return;

    int channel_stride = H * W;
    int c = (idx / channel_stride) % C;

    float val = input[idx] + bias[c];
    val = fmaxf(0.0f, fminf(val, 1.0f));
    val *= scaling_factor;
    val = fmaxf(0.0f, fminf(val, 1.0f));
    val /= scaling_factor;
    output[idx] = val;
}

torch::Tensor fused_ops_rocm(torch::Tensor x, torch::Tensor bias, float scaling_factor) {
    auto out = torch::empty_like(x);
    if (!x.is_contiguous()) x = x.contiguous();
    if (!bias.is_contiguous()) bias = bias.contiguous();

    float* input_ptr = x.data_ptr<float>();
    float* bias_ptr = bias.data_ptr<float>();
    float* output_ptr = out.data_ptr<float>();

    int num_elements = x.numel();
    int C = x.size(1);
    int H = x.size(2);
    int W = x.size(3);

    const int block_size = 256;
    int grid_size = (num_elements + block_size - 1) / block_size;

    hipLaunchKernelGGL(fused_op_kernel, 
                       dim3(grid_size), 
                       dim3(block_size),
                       0,
                       at::hip::getCurrentHIPStream(),
                       input_ptr,
                       bias_ptr,
                       output_ptr,
                       num_elements,
                       C,
                       H,
                       W,
                       scaling_factor);

    return out;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void avg_pool2d_kernel(const float* input, float* output, int batch_size, int channels, int height, int width, int kernel_size, int stride, int padding) {
    int output_height = (height + 2 * padding - kernel_size) / stride + 1;
    int output_width = (width + 2 * padding - kernel_size) / stride + 1;
    int output_size = output_height * output_width;

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < batch_size * channels * output_size) {
        int b = idx / (channels * output_size);
        int c = (idx % (channels * output_size)) / output_size;
        int oh = (idx % output_size) / output_width;
        int ow = idx % output_width;

        float sum = 0.0f;
        int count = 0;

        for (int kh = 0; kh < kernel_size; ++kh) {
            for (int kw = 0; kw < kernel_size; ++kw) {
                int ih = oh * stride + kh - padding;
                int iw = ow * stride + kw - padding;

                if (ih >= 0 && ih < height && iw >= 0 && iw < width) {
                    sum += input[b * channels * height * width + c * height * width + ih * width + iw];
                    count++;
                }
            }
        }

        output[b * channels * output_size + c * output_size + oh * output_width + ow] = sum / count;
    }
}

torch::Tensor avg_pool2d_rocm(torch::Tensor input, int kernel_size, int stride, int padding) {
    auto batch_size = input.size(0);
    auto channels = input.size(1);
    auto height = input.size(2);
    auto width = input.size(3);
    int output_height = (height + 2 * padding - kernel_size) / stride + 1;
    int output_width = (width + 2 * padding - kernel_size) / stride + 1;
    auto output = torch::zeros({batch_size, channels, output_height, output_width}, torch::kFloat32).to(input.device());

    int size = batch_size * channels * output_height * output_width;
    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    avg_pool2d_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), output.data_ptr<float>(), batch_size, channels, height, width, kernel_size, stride, padding);

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void layer_norm_kernel(const float* x, const float* gamma, const float* beta, float* out, int outer_size, int inner_size, float epsilon) {
    int outer_idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (outer_idx < outer_size) {
        float sum = 0.0f;
        float sum_sq = 0.0f;

        for (int inner_idx = 0; inner_idx < inner_size; ++inner_idx) {
            float val = x[outer_idx * inner_size + inner_idx];
            sum += val;
            sum_sq += val * val;
        }

        float mean = sum / inner_size;
        float var = (sum_sq / inner_size) - (mean * mean);
        float inv_std = rsqrtf(var + epsilon);

        for (int inner_idx = 0; inner_idx < inner_size; ++inner_idx) {
            out[outer_idx * inner_size + inner_idx] = gamma[inner_idx] * (x[outer_idx * inner_size + inner_idx] - mean) * inv_std + beta[inner_idx];
        }
    }
}

torch::Tensor layer_norm_rocm(torch::Tensor x, torch::Tensor gamma, torch::Tensor beta, float epsilon) {
    int outer_size = x.numel() / gamma.numel();
    auto out = torch::empty_like(x);

    const int block_size = 256;
    const int num_blocks = (outer_size + block_size - 1) / block_size;

    hipLaunchKernelGGL(layer_norm_kernel, num_blocks, block_size, 0, 0, x.data_ptr<float>(), gamma.data_ptr<float>(), beta.data_ptr<float>(), out.data_ptr<float>(), outer_size, gamma.numel(), epsilon);

    return out;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>

__global__ void conv_transpose3d_kernel(
    const float* input, const float* weight, const float* bias, float* output,
    int batch_size, int in_channels, int out_channels,
    int input_depth, int input_height, int input_width,
    int output_depth, int output_height, int output_width,
    int kernel_d, int kernel_h, int kernel_w,
    int stride_d, int stride_h, int stride_w,
    int pad_d, int pad_h, int pad_w,
    int op_d, int op_h, int op_w,
    int groups, int icpg, int ocpg
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = batch_size * out_channels * output_depth * output_height * output_width;
    if (idx >= total) return;

    int remaining = idx;
    int batch = remaining / (out_channels * output_depth * output_height * output_width);
    remaining %= (out_channels * output_depth * output_height * output_width);
    int out_chan = remaining / (output_depth * output_height * output_width);
    remaining %= (output_depth * output_height * output_width);
    int out_d = remaining / (output_height * output_width);
    remaining %= (output_height * output_width);
    int out_h = remaining / output_width;
    int out_w = remaining % output_width;

    int group = out_chan / ocpg;
    int out_cg = out_chan % ocpg;

    float sum = (bias != nullptr) ? bias[out_chan] : 0.0f;

    for(int ic = 0; ic < icpg; ++ic) {
        for(int kd = 0; kd < kernel_d; ++kd) {
            for(int kh = 0; kh < kernel_h; ++kh) {
                for(int kw = 0; kw < kernel_w; ++kw) {
                    int in_d = (out_d - kd + pad_d) / stride_d;
                    if ((out_d - kd + pad_d) % stride_d != 0) continue;
                    int in_h = (out_h - kh + pad_h) / stride_h;
                    if ((out_h - kh + pad_h) % stride_h != 0) continue;
                    int in_w = (out_w - kw + pad_w) / stride_w;
                    if ((out_w - kw + pad_w) % stride_w != 0) continue;

                    if(in_d >= 0 && in_d < input_depth && in_h >= 0 && in_h < input_height && in_w >= 0 && in_w < input_width) {
                        int in_chan = group * icpg + ic;
                        int input_idx = (((batch * in_channels + in_chan) * input_depth + in_d) * input_height + in_h) * input_width + in_w;
                        int weight_idx = (((in_chan * ocpg + out_cg) * kernel_d + kd) * kernel_h + kh) * kernel_w + kw;

                        sum += input[input_idx] * weight[weight_idx];
                    }
                }
            }
        }
    }

    output[idx] = sum;
}

torch::Tensor conv_transpose3d_rocm(torch::Tensor input, torch::Tensor weight, c10::optional<torch::Tensor> bias,
                                   int sd, int sh, int sw, int pd, int ph, int pw, 
                                   int op_d, int op_h, int op_w, int groups, int icpg, int ocpg) {
    auto input_sizes = input.sizes();
    int batch_size = input.size(0);
    int input_depth = input.size(2);
    int input_height = input.size(3);
    int input_width = input.size(4);

    int kernel_d = weight.size(2);
    int kernel_h = weight.size(3);
    int kernel_w = weight.size(4);

    int output_depth = (input_depth-1)*sd + kernel_d - 2*pd + op_d;
    int output_height = (input_height-1)*sh + kernel_h - 2*ph + op_h;
    int output_width = (input_width-1)*sw + kernel_w - 2*pw + op_w;

    auto opts = torch::TensorOptions().dtype(input.dtype()).device(input.device());
    auto output = torch::zeros({batch_size, groups*ocpg, output_depth, output_height, output_width}, opts);
    const float* bias_ptr = bias.has_value() ? bias->data_ptr<float>() : nullptr;

    int total_elements = output.numel();
    int block_size = 256;
    int grid_size = (total_elements + block_size - 1) / block_size;

    hipLaunchKernelGGL(conv_transpose3d_kernel, grid_size, block_size, 0, 0, 
        input.data_ptr<float>(), weight.data_ptr<float>(), bias_ptr, output.data_ptr<float>(),
        batch_size, input.size(1), groups*ocpg,
        input_depth, input_height, input_width,
        output_depth, output_height, output_width,
        kernel_d, kernel_h, kernel_w,
        sd, sh, sw,
        pd, ph, pw,
        op_d, op_h, op_w,
        groups, icpg, ocpg
    );

    return output.contiguous();
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
