__global__ void hardsigmoid_kernel(const float* x, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = x[idx];
        out[idx] = fmaxf(0.0f, fminf(1.0f, val * 0.16666667f + 0.5f)); // Correct coefficients for HardSigmoid
    }
}

