__global__ void maxpool1d_kernel(const float* input, float* output, int batch_size, int num_features, int input_length, int kernel_size, int stride, int padding, int dilation) {
    int output_length = (input_length + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int b = idx / (num_features * output_length);
    int f = (idx / output_length) % num_features;
    int o = idx % output_length;
    if (b < batch_size && f < num_features && o < output_length) {
        float max_val = -INFINITY;
        for (int k = 0; k < kernel_size; ++k) {
            int input_idx = (o * stride) - padding + (k * dilation);
            if (input_idx >= 0 && input_idx < input_length) {
                float val = input[b * num_features * input_length + f * input_length + input_idx];
                if (val > max_val) max_val = val;
            }
        }
        output[b * num_features * output_length + f * output_length + o] = max_val;
    }
}

torch::Tensor maxpool1d_rocm(torch::Tensor input, int kernel_size, int stride, int padding, int dilation) {
    int batch_size = input.size(0);
    int num_features = input.size(1);
    int input_length = input.size(2);
    int output_length = (input_length + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;
    auto output = torch::zeros({batch_size, num_features, output_length}, input.options());

    const int block_size = 256;
    const int grid_size = (batch_size * num_features * output_length + block_size - 1) / block_size;

    hipLaunchKernelGGL(
        maxpool1d_kernel,
        dim3(grid_size),
        dim3(block_size),
        0,
        at::hip::getCurrentHIPStream(),
        input.contiguous().data_ptr<float>(),
        output.contiguous().data_ptr<float>(),
        batch_size,
        num_features,
        input_length,
        kernel_size,
        stride,
        padding,
        dilation
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_post_conv_ops_kernel(const float* x_conv, const float* bias, float* out, int num_elements, int channels, int depth, int height, int width) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= num_elements) return;

    int s = idx;
    int w = s % width;
    s /= width;
    int h = s % height;
    s /= height;
    int d = s % depth;
    s /= depth;
    int c = s % channels;
    s /= channels;

    float x_val = x_conv[idx];
    float bias_val = bias[c];

    float step1 = x_val + bias_val;
    float step2 = step1 + x_val;
    float step3 = step2 * x_val;
    float step4 = step3 + x_val;

    out[idx] = step4;
}

torch::Tensor fused_post_conv_ops_rocm(torch::Tensor x_conv, torch::Tensor bias) {
    auto out = torch::empty_like(x_conv);
    int num_elements = x_conv.numel();

    auto sizes = x_conv.sizes();
    int channels = sizes[1];
    int depth = sizes[2];
    int height = sizes[3];
    int width = sizes[4];

    const int block_size = 256;
    dim3 threads(block_size);
    dim3 blocks((num_elements + block_size - 1) / block_size);

    hipLaunchKernelGGL(fused_post_conv_ops_kernel, blocks, threads, 0, 0, 
        x_conv.data_ptr<float>(), 
        bias.data_ptr<float>(), 
        out.data_ptr<float>(), 
        num_elements, channels, depth, height, width
    );

    return out;
}

#include <torch/extension.h>
