__global__ void fused_kernel(const float* input, float* output, const float* weight, const float* bias,
                             int N, int C, int G, float eps, float slope, float scale) {
    extern __shared__ float smem[];
    float* s_sum = smem;
    float* s_sqsum = s_sum + blockDim.x;

    int n = blockIdx.x;
    int g = blockIdx.y;
    int c_start = g * (C/G);
    int c_end = c_start + (C/G);
    int tid = threadIdx.x;

    float sum = 0.0f, sqsum = 0.0f;
    for (int c = c_start + tid; c < c_end; c += blockDim.x) {
        float val = input[n*C + c];
        sum += val;
        sqsum += val * val;
    }
    s_sum[tid] = sum;
    s_sqsum[tid] = sqsum;
    __syncthreads();

    for (int stride=blockDim.x/2; stride>0; stride>>=1) {
        if (tid < stride) {
            s_sum[tid] += s_sum[tid+stride];
            s_sqsum[tid] += s_sqsum[tid+stride];
        }
        __syncthreads();
    }

    if (tid == 0) {
        float mean = s_sum[0] / (C/G);
        float var = (s_sqsum[0]/(C/G) - mean*mean) + eps;
        float inv_std = rsqrtf(var);
        s_sum[0] = mean;
        s_sqsum[0] = inv_std * scale;
    }
    __syncthreads();

    float inv_std_scaled = s_sqsum[0];
    for (int c = c_start + tid; c < c_end; c += blockDim.x) {
        float x = input[n*C + c];
        float norm = (x - s_sum[0]) * inv_std_scaled * weight[c] + bias[c];
        output[n*C + c] = (norm > 0) ? norm : norm * slope;
    }
}

torch::Tensor fused_op(torch::Tensor x, torch::Tensor w, torch::Tensor b, 
                      int groups, float eps, float slope, float scale) {
    auto out = torch::empty_like(x);
    int N = x.size(0);
    int C = x.size(1);
    dim3 grid(N, groups);
    int block = 256;
    size_t smem = 2 * block * sizeof(float);
    fused_kernel<<<grid, block, smem>>>(
        x.data_ptr<float>(), out.data_ptr<float>(), 
        w.data_ptr<float>(), b.data_ptr<float>(),
        N, C, groups, eps, slope, scale
    );
    return out;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void sub_mish_kernel(const float* input, float* output, float subtract_val, int num_elements) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < num_elements) {
        float x = input[idx] - subtract_val;
        float sp = log1pf(expf(x));
        float tanh_sp = tanhf(sp);
        output[idx] = x * tanh_sp;
    }
}

torch::Tensor sub_and_mish_rocm(torch::Tensor input, float subtract_val) {
    auto num_elements = input.numel();
    auto output = torch::empty_like(input);

    int block_size = 256;
    int num_blocks = (num_elements + block_size - 1) / block_size;

    hipLaunchKernelGGL(sub_mish_kernel, dim3(num_blocks), dim3(block_size), 0, at::hip::getCurrentHIPStream(), 
        input.data_ptr<float>(), output.data_ptr<float>(), subtract_val, num_elements);

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void matmul_kernel(const float* A, const float* B, float* out, int M, int K) {
    __shared__ float B_shr[16][16];

    int i = blockIdx.x * blockDim.x + threadIdx.x;
    int j_block = blockIdx.y * blockDim.y;
    int j = j_block + threadIdx.y;

    if (j >= M) return;

    for (int k = 0; k < K; ++k) {
        B_shr[k][threadIdx.y] = B[k * M + j];
    }
    __syncthreads();

    if (i >= M) return;

    float sum = 0.0f;
    for (int k = 0; k < K; ++k) {
        sum += A[i * K + k] * B_shr[k][threadIdx.y];
    }
    out[i * M + j] = sum;
}

torch::Tensor matmul_rocm(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "Inputs must be 2D");
    int M = A.size(0);
    int K = A.size(1);
    TORCH_CHECK(B.size(0) == K, "Invalid dimensions");

    auto out = torch::zeros({M, M}, A.options());

    dim3 block(32, 16);
    dim3 grid((M + block.x - 1) / block.x, (M + block.y - 1) / block.y);

    hipLaunchKernelGGL(matmul_kernel, grid, block, 0, at::hip::getCurrentHIPStream(), 
        A.data_ptr<float>(), B.data_ptr<float>(), out.data_ptr<float>(), M, K);

    return out;
}

