__global__ void elu_kernel(const float* x, float* out, float alpha, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = x[idx] > 0 ? x[idx] : alpha * (expf(x[idx]) - 1);
    }
}

torch::Tensor elu_rocm(torch::Tensor x, float alpha) {
    auto size = x.numel();
    auto out = torch::zeros_like(x);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    elu_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), out.data_ptr<float>(), alpha, size);

    return out;
}

#include <torch/extension.h>  
#include <hip/hip_runtime.h>  

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {  
    int row = blockIdx.y * blockDim.y + threadIdx.y;  
    int col = blockIdx.x * blockDim.x + threadIdx.x;  
    if (row < N && col < N) {  
        float sum = 0.0f;  
        for (int k = 0; k < N; ++k) {  
            sum += A[row * N + k] * B[k * N + col];  
        }  
        C[row * N + col] = sum;  
    }  
}  

torch::Tensor matmul_rocm(torch::Tensor A, torch::Tensor B, int N) {  
    auto C = torch::zeros({N, N}, A.options());  
    dim3 threads(16, 16);  
    dim3 blocks((N + threads.x - 1) / threads.x, (N + threads.y - 1) / threads.y);  
    hipLaunchKernelGGL(matmul_kernel, blocks, threads, 0, 0, A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);  
    return C;  
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>
#include <math.h>

__global__ void fused_act_kernel(const float* input, float* output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float x = input[idx];
        x = fmaxf(0.01f * x, x);
        x = fmaxf(0.01f * x, x);
        const float kSqrtTwoOverPi = 0.7978845608028654f;
        float inner = x + 0.044715f * x * x * x;
        float gelu_x = 0.5f * x * (1.0f + tanhf(kSqrtTwoOverPi * inner));
        inner = gelu_x + 0.044715f * gelu_x * gelu_x * gelu_x;
        gelu_x = 0.5f * gelu_x * (1.0f + tanhf(kSqrtTwoOverPi * inner));
        output[idx] = gelu_x;
    }
}

torch::Tensor fused_activations_rocm(torch::Tensor x) {
    auto output = torch::empty_like(x);
    int size = x.numel();
    const int block_size = 256;
    int num_blocks = (size + block_size - 1) / block_size;
    hipLaunchKernelGGL(fused_act_kernel, 
        dim3(num_blocks), dim3(block_size), 0, 0, 
        x.data_ptr<float>(), 
        output.data_ptr<float>(), 
        size
    );
    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_bn_scaling_kernel(const float* input, const float* a, const float* b, float* output, int N, int C, int H, int W) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = N * C * H * W;
    if (idx >= total_elements) return;

    int c = (idx / (H * W)) % C;
    output[idx] = input[idx] * a[c] + b[c];
}

torch::Tensor fused_bn_scaling_rocm(torch::Tensor input, torch::Tensor a, torch::Tensor b) {
    auto output = torch::empty_like(input);
    auto sizes = input.sizes();
    int N = sizes[0], C = sizes[1], H = sizes[2], W = sizes[3];
    int num_elements = input.numel();

    const int block_size = 256;
    int num_blocks = (num_elements + block_size - 1) / block_size;

    hipLaunchKernelGGL(fused_bn_scaling_kernel, num_blocks, block_size, 0, 0, 
        input.data_ptr<float>(), 
        a.data_ptr<float>(), 
        b.data_ptr<float>(), 
        output.data_ptr<float>(),
        N, C, H, W
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void avg_pool1d_kernel(const float* input, float* output, int batch_size, int in_channels, int input_length, int output_length, int kernel_size, int stride, int padding) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int channel = blockIdx.y;
    int batch = blockIdx.z;
    if (idx < output_length && channel < in_channels && batch < batch_size) {
        float sum = 0.0f;
        int start = idx * stride - padding;
        int end = start + kernel_size;
        start = max(start, 0);
        end = min(end, input_length);
        int count = end - start;
        for (int i = start; i < end; ++i) {
            sum += input[batch * in_channels * input_length + channel * input_length + i];
        }
        output[batch * in_channels * output_length + channel * output_length + idx] = sum / (float)kernel_size;
    }
}

torch::Tensor avg_pool1d_rocm(torch::Tensor input, int kernel_size, int stride, int padding) {
    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int input_length = input.size(2);
    int output_length = (input_length + 2 * padding - kernel_size) / stride + 1;
    auto output = torch::zeros({batch_size, in_channels, output_length}, input.options());

    dim3 block_size(256);
    dim3 grid_size((output_length + block_size.x - 1) / block_size.x, in_channels, batch_size);

    hipStream_t stream = at::hip::getCurrentHIPStreamMasqueradingAsCUDA();
    avg_pool1d_kernel<<<grid_size, block_size, 0, stream>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        input_length,
        output_length,
        kernel_size,
        stride,
        padding
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>

__global__ void conv1x1_kernel(
    const float* input,
    const float* weight,
    const float* bias,
    float* output,
    int batch_size,
    int in_channels,
    int out_channels,
    int height,
    int width,
    int input_stride_batch,
    int input_stride_channel,
    int input_stride_height,
    int input_stride_width,
    int weight_stride_co,
    int weight_stride_ci
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = batch_size * out_channels * height * width;
    if (idx >= total) return;

    int elements_per_batch = out_channels * height * width;
    int b = idx / elements_per_batch;
    int tid = idx % elements_per_batch;
    int co = tid / (height * width);
    int spatial_idx = tid % (height * width);
    int h = spatial_idx / width;
    int w = spatial_idx % width;

    float sum = 0.0f;
    for (int ci = 0; ci < in_channels; ++ci) {
        int input_offset = b * input_stride_batch
                         + ci * input_stride_channel
                         + h * input_stride_height
                         + w * input_stride_width;
        int weight_offset = co * weight_stride_co
                          + ci * weight_stride_ci;
        sum += input[input_offset] * weight[weight_offset];
    }

    if (bias != nullptr) {
        sum += bias[co];
    }

    output[idx] = sum;
}

torch::Tensor conv1x1_rocm(torch::Tensor input, torch::Tensor weight, torch::Tensor bias) {
    auto input_cont = input.contiguous();
    auto weight_cont = weight.contiguous().view({weight.size(0), weight.size(1)});
    auto bias_cont = bias.defined() ? bias.contiguous() : torch::Tensor();

    auto output = torch::zeros({input_cont.size(0), weight_cont.size(0), input_cont.size(2), input_cont.size(3)}, input_cont.options());

    const float* input_ptr = input_cont.data_ptr<float>();
    const float* weight_ptr = weight_cont.data_ptr<float>();
    const float* bias_ptr = bias_cont.defined() ? bias_cont.data_ptr<float>() : nullptr;
    float* output_ptr = output.data_ptr<float>();

    auto input_strides = input_cont.strides();
    auto weight_strides = weight_cont.strides();

    int total_elements = output.numel();
    int threads = 256;
    int blocks = (total_elements + threads - 1) / threads;

    hipLaunchKernelGGL(conv1x1_kernel,
                    dim3(blocks), dim3(threads), 0, 0,
                    input_ptr,
                    weight_ptr,
                    bias_ptr,
                    output_ptr,
                    input_cont.size(0),
                    input_cont.size(1),
                    weight_cont.size(0),
                    input_cont.size(2),
                    input_cont.size(3),
                    input_strides[0],
                    input_strides[1],
                    input_strides[2],
                    input_strides[3],
                    weight_strides[0],
                    weight_strides[1]);

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void matrix_scalar_mul_kernel(const float* A, float s, float* C, int M, int N) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row < M && col < N) {
        int idx = row * N + col;
        C[idx] = A[idx] * s;
    }
}

torch::Tensor matrix_scalar_mul_rocm(torch::Tensor A, float s) {
    int M = A.size(0);
    int N = A.size(1);
    auto C = torch::zeros_like(A);

    dim3 blockDim(16, 16);
    dim3 gridDim((N + blockDim.x - 1) / blockDim.x, (M + blockDim.y - 1) / blockDim.y);

    matrix_scalar_mul_kernel<<<gridDim, blockDim>>>(A.data_ptr<float>(), s, C.data_ptr<float>(), M, N);

    return C;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void conv3d_custom_kernel(
    const float* input, const float* weight, const float* bias, float* output,
    int batch_size, int input_channels, int D_in, int H_in, int W_in,
    int output_channels, int kernel_d, int kernel_h, int kernel_w,
    int D_out, int H_out, int W_out
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    const int total = batch_size * output_channels * D_out * H_out * W_out;

    if (idx < total) {
        const int n = idx / (output_channels * D_out * H_out * W_out);
        int rem = idx % (output_channels * D_out * H_out * W_out);
        const int c = rem / (D_out * H_out * W_out);
        rem = rem % (D_out * H_out * W_out);
        const int d = rem / (H_out * W_out);
        rem = rem % (H_out * W_out);
        const int h = rem / W_out;
        const int w = rem % W_out;

        float acc = 0.0f;
        for (int ci = 0; ci < input_channels; ++ci) {
            for (int kd = 0; kd < kernel_d; ++kd) {
                const int dz = d * 1 + kd - 0; // stride=1, padding=0
                if (dz < 0 || dz >= D_in) continue;
                for (int kh = 0; kh < kernel_h; ++kh) {
                    const int hz = h * 1 + kh - 0; 
                    if (hz < 0 || hz >= H_in) continue;
                    for (int kw = 0; kw < kernel_w; ++kw) {
                        const int wz = w * 1 + kw - 0;
                        if (wz < 0 || wz >= W_in) continue;

                        const int inp_idx = n * input_channels * D_in * H_in * W_in
                            + ci * D_in * H_in * W_in
                            + dz * H_in * W_in
                            + hz * W_in + wz;

                        const int weight_idx = c * input_channels * kernel_d * kernel_h * kernel_w
                            + ci * kernel_d * kernel_h * kernel_w
                            + kd * kernel_h * kernel_w + kh * kernel_w + kw;

                        acc += input[inp_idx] * weight[weight_idx];
                    }
                }
            }
        }

        if (bias != nullptr) {
            acc += bias[c];
        }

        output[idx] = acc;
    }
}

torch::Tensor conv3d_custom(
    torch::Tensor input, torch::Tensor weight, torch::Tensor bias,
    int kernel_d, int kernel_h, int kernel_w,
    int D_out, int H_out, int W_out
) {
    const int batch_size = input.size(0);
    const int input_channels = input.size(1);
    const int D_in = input.size(2);
    const int H_in = input.size(3);
