    int depth = input.size(2);
    int height = input.size(3);
    int width = input.size(4);

    auto output = torch::empty({batch_size, depth, height, width}, input.options());
    int total = batch_size * depth * height * width;
    int block_size = 256;
    int grid_size = (total + block_size - 1) / block_size;

    hipLaunchKernelGGL(clamp_mult_max_kernel,
        dim3(grid_size), dim3(block_size), 0, at::hip::getCurrentHIPStream(),
        input.data_ptr<float>(), multiplier.data_ptr<float>(), output.data_ptr<float>(),
        clamp_min, clamp_max,
