    int output_length = ((input_length - dilation*(kernel_size-1) -1)/stride) +1;
    auto output = torch::zeros({batch_size, out_channels, output_length}, x.options());

    dim3 threads(8, 8, 8);
    dim3 blocks(
        (batch_size + threads.x -1)/threads.x,
        (out_channels + threads.y -1)/threads.y,
        (output_length + threads.z -1)/threads.z
