__global__ void log_softmax_kernel(const float* x, float* out, int batch_size, int dim) {
    int batch_idx = blockIdx.x;
    int idx = threadIdx.x;

    if (batch_idx >= batch_size || idx >= dim) return;

    extern __shared__ float shared_max[];
    extern __shared__ float shared_exp_sum[];

    float max_val = -std::numeric_limits<float>::infinity();
    for (int i = 0; i < dim; i += blockDim.x) {
        int col = i + idx;
        if (col < dim) {
            float val = x[batch_idx * dim + col];
            if (val > max_val) {
                max_val = val;
            }
        }
    }

    shared_max[idx] = max_val;
    __syncthreads();

    for (int i = blockDim.x / 2; i > 0; i /= 2) {
        if (idx < i && idx + i < blockDim.x) {
            if (shared_max[idx + i] > shared_max[idx]) {
                shared_max[idx] = shared_max[idx + i];
            }
        }
        __syncthreads();
    }

    max_val = shared_max[0];

    float sum_exp = 0.0f;
    for (int i = 0; i < dim; i += blockDim.x) {
        int col = i + idx;
        if (col < dim) {
            sum_exp += __expf(x[batch_idx * dim + col] - max_val);
        }
    }

    shared_exp_sum[idx] = sum_exp;
    __syncthreads();

    for (int i = blockDim.x / 2; i > 0; i /= 2) {
        if (idx < i && idx + i < blockDim.x) {
            shared_exp_sum[idx] += shared_exp_sum[idx + i];
        }
        __syncthreads();
    }

    float log_sum_exp = __logf(shared_exp_sum[0]);

    for (int i = 0; i < dim; i += blockDim.x) {
        int col = i + idx;
        if (col < dim) {
            out[batch_idx * dim + col] = x[batch_idx * dim + col] - max_val - log_sum_exp;
        }
    }
}

