    auto sizes = x.sizes();
    int batch_size = sizes[0];
    int dim_size = sizes[1];
    auto out = torch::zeros_like(x);

    int threads = min(dim_size, 256);
    int shared_memory_size = threads * 2 * sizeof(float);

    log_softmax_kernel<<<batch_size, threads, shared_memory_size>>>(x.data_ptr<float>(), out.data_ptr<float>(), batch_size, dim_size);

