__global__ void fused_matmul_avgpool_kernel(const float* x, const float* weight, const float* bias, float* output, int batch_size, int in_features, int out_features, int pool_size) {
    const int pooled_out = out_features / pool_size;
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    const int b = idx / pooled_out;
    const int j = idx % pooled_out;

    if (b >= batch_size || j >= pooled_out) return;

    float sum_val = 0.0f;

    for (int k = 0; k < pool_size; ++k) {
        const int row = j * pool_size + k;
        if (row >= out_features) break;

        float dot = 0.0f;
        for (int d = 0; d < in_features; ++d) {
            dot += x[b * in_features + d] * weight[row * in_features + d];
        }
        dot += bias[row];
        sum_val += dot;
    }

    sum_val /= pool_size;

    output[b * pooled_out + j] = sum_val;
}

torch::Tensor fused_matmul_avgpool_rocm(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, int pool_size) {
    TORCH_CHECK(x.dim() == 2, "Expected x to be 2-dimensional");
    const int batch_size = x.size(0);
    const int in_features = x.size(1);
    const int out_features = weight.size(0);
    const int pooled_out = out_features / pool_size;

    auto output = torch::zeros({batch_size, pooled_out}, x.options());

    const int total_threads = batch_size * pooled_out;
    const int block_size = 256;
    const int num_blocks = (total_threads + block_size - 1) / block_size;

    hipLaunchKernelGGL(fused_matmul_avgpool_kernel,
        dim3(num_blocks), dim3(block_size), 0, at::hip::getCurrentHIPStream(),
        x.data_ptr<float>(), weight.data_ptr<float>(), bias.data_ptr<float>(), output.data_ptr<float>(),
        batch_size, in_features, out_features, pool_size
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void selu_kernel(const float* x, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float alpha = 1.6732632423543772848170429916717f;
        float scale = 1.0507009873554804934193349852946f;
        float val = x[idx];
        out[idx] = scale * (val >= 0 ? val : alpha * (expf(val) - 1));
    }
}

torch::Tensor selu_rocm(torch::Tensor x) {
    auto size = x.numel();
    auto out = torch::zeros_like(x);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    selu_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

#define TILE_SIZE 16
#define THREADS_PER_BLOCK 256

__global__ void matmul_kernel(const float* __restrict__ A, 
                              const float* __restrict__ B,
                              float* __restrict__ C,
                              int M, int N, int K) {

    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    float acc = 0.0;

    for (int t = 0; t < (K + TILE_SIZE - 1)/TILE_SIZE; ++t) {
        int aCol = t * TILE_SIZE + threadIdx.x;
        int bRow = t * TILE_SIZE + threadIdx.y;

        if(row < M && aCol < K) As[threadIdx.y][threadIdx.x] = A[row*K + aCol];
        else As[threadIdx.y][threadIdx.x] = 0.0f;

        if(col < N && bRow < K) Bs[threadIdx.y][threadIdx.x] = B[bRow*N + col];
        else Bs[threadIdx.y][threadIdx.x] = 0.0f;

        __syncthreads();

        #pragma unroll
        for(int k = 0; k < TILE_SIZE; ++k) {
            acc += As[threadIdx.y][k] * Bs[k][threadIdx.x];
        }
        __syncthreads();
    }

    if(row < M && col < N) {
        C[row*N + col] = acc;
    }
}

torch::Tensor matmul_rocm(torch::Tensor A, torch::Tensor B) {
    int M = A.size(0);
    int K = A.size(1);
    int N = B.size(1);
    auto C = torch::empty({M, N}, A.options());

    dim3 threads(TILE_SIZE, TILE_SIZE);
    dim3 blocks((N + threads.x - 1)/threads.x, (M + threads.y - 1)/threads.y);

    hipStream_t stream = at::hip::getCurrentHIPStream().stream();
    matmul_kernel<<<blocks, threads, 0, stream>>>(
        A.data_ptr<float>(), 
        B.data_ptr<float>(), 
        C.data_ptr<float>(),
        M, N, K
    );

    return C;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>

__global__ void fused_layernorm_gelu_scaling_kernel(
    const float* input, const float* gamma, const float* beta,
    float* output, float scaling_factor, float eps,
    int N, int C, int D, int H, int W
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= N * C * D * H * W) return;

    int c = (idx / (D * H * W)) % C;

    float mean = 0.0f;
    float var = 0.0f;
    const float* group_input = input + (idx / W) * W;

    for(int i = 0; i < W; ++i) {
        mean += group_input[i];
    }
    mean /= W;

    for(int i = 0; i < W; ++i) {
        var += (group_input[i] - mean) * (group_input[i] - mean);
    }
    var /= W;

    float x = input[idx];
    float normalized = (x - mean) / sqrt(var + eps);
    float scaled = normalized * gamma[c] + beta[c];
    float gelu = 0.5f * scaled * (1.0f + erff(scaled / 1.41421356237f));
    output[idx] = gelu * scaling_factor;
}

torch::Tensor fused_op_rocm(
    torch::Tensor input, torch::Tensor gamma, torch::Tensor beta,
    float scaling_factor, float eps
) {
    auto out = torch::empty_like(input);
    int num_elements = input.numel();
    const int block_size = 256;
    int grid_size = (num_elements + block_size - 1) / block_size;

    hipLaunchKernelGGL(
        fused_layernorm_gelu_scaling_kernel,
        grid_size, block_size, 0, 0,
        input.data_ptr<float>(), gamma.data_ptr<float>(), beta.data_ptr<float>(),
        out.data_ptr<float>(), scaling_factor, eps,
        input.size(0), input.size(1), input.size(2), input.size(3), input.size(4)
    );
    return out;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void depthwise_conv_kernel(
    const float* input,
    const float* weight,
    float* output,
    int batch_size,
    int in_channels,
    int H_in,
    int W_in,
    int K,
    int H_out,
    int W_out,
    int stride_h,
    int padding_h,
    int dilation_h
) {
    const int global_idx = blockIdx.x * blockDim.x + threadIdx.x;
    const int total_output = batch_size * in_channels * H_out * W_out;
    if (global_idx >= total_output) return;

    int n = global_idx / (in_channels * H_out * W_out);
    int rem = global_idx % (in_channels * H_out * W_out);
    int c = rem / (H_out * W_out);
    rem = rem % (H_out * W_out);
    int h_out = rem / W_out;
    int w_out = rem % W_out;

    const float* weight_ptr = weight + c * K;
    float sum = 0.0f;

    for (int k = 0; k < K; ++k) {
        int h_in = h_out * stride_h - padding_h + k * dilation_h;
        if (h_in >= 0 && h_in < H_in) {
            int input_idx = n * in_channels * H_in * W_in + c * H_in * W_in + h_in * W_in + w_out;
            sum += input[input_idx] * weight_ptr[k];
        }
    }

    output[global_idx] = sum;
}

torch::Tensor depthwise_conv_rocm(
    torch::Tensor input,
    torch::Tensor weight,
    int H_kernel,
    int stride_h,
    int padding_h,
    int dilation_h
) {
    auto batch_size = input.size(0);
    auto in_channels = input.size(1);
    int H_in = input.size(2);
    int W_in = input.size(3);

    int H_out = (H_in + 2 * padding_h - dilation_h * (H_kernel - 1) - 1) / stride_h + 1;
    int W_out = W_in;

    auto output = torch::zeros({batch_size, in_channels, H_out, W_out}, input.options());
    int total_output = output.numel();

    const int block_size = 256;
    int num_blocks = (total_output + block_size - 1) / block_size;

    depthwise_conv_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        H_in,
        W_in,
        H_kernel,
        H_out,
        W_out,
        stride_h,
        padding_h,
        dilation_h
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_sub_tanh_kernel(const float* input, const float* bias, float* output, int batch_size, int out_channels, int height, int width) {
    int index = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * out_channels * height * width;
    if (index < total_elements) {
        int n = index / (out_channels * height * width);
        int c = (index % (out_channels * height * width)) / (height * width);
        float bias_val = bias[c];
        output[index] = tanhf(input[index] - bias_val);
    }
}

torch::Tensor fused_sub_tanh_rocm(torch::Tensor input, torch::Tensor bias) {
    auto output = torch::zeros_like(input);
    int total_elements = input.numel();
    const int block_size = 256;
    int num_blocks = (total_elements + block_size - 1) / block_size;

    fused_sub_tanh_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), bias.data_ptr<float>(), output.data_ptr<float>(), 
        input.size(0), input.size(1), input.size(2), input.size(3));

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_relu_hardswish_kernel(const float* input, float* output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float x = input[idx];
        x = fmaxf(0.0f, x);
        float temp = (x + 3.0f) / 6.0f;
        temp = fminf(temp, 1.0f);
        output[idx] = x * temp;
    }
}

torch::Tensor fused_relu_hardswish_rocm(torch::Tensor input) {
    auto output = torch::empty_like(input);
    int size = input.numel();

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    hipLaunchKernelGGL(fused_relu_hardswish_kernel, 
        dim3(num_blocks), 
        dim3(block_size), 
        0, 
        at::hip::getCurrentHIPStream(), 
        input.data_ptr<float>(), 
        output.data_ptr<float>(), 
        size
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <vector>

__global__ void conv3d_kernel(
    const float* input, const float* weight, float* output,
    int N, int C_in, int C_out,
    int D_in, int H_in, int W_in,
    int Kd, int Kh, int Kw,
    int pad_d, int pad_h, int pad_w,
    int stride_d, int stride_h, int stride_w,
    int dilation_d, int dilation_h, int dilation_w,
    int groups,
    int D_out, int H_out, int W_out) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= N * C_out * D_out * H_out * W_out) return;

    int remaining = idx;
    const int w_out = remaining % W_out; remaining /= W_out;
    const int h_out = remaining % H_out; remaining /= H_out;
    const int d_out = remaining % D_out; remaining /= D_out;
    const int c_out = remaining % C_out; remaining /= C_out;
    const int n = remaining;

    const int group_in_channels = C_in / groups;
    const int group_idx = c_out / (C_out / groups);
    const int c_in_start = group_idx * group_in_channels;

    float sum = 0.0f;
    for (int c_in = c_in_start; c_in < c_in_start + group_in_channels; c_in++) {
        for (int kd = 0; kd < Kd; kd++) {
            const int d_in = d_out * stride_d - pad_d + kd * dilation_d;
            if (d_in < 0 || d_in >= D_in) continue;

            for (int kh = 0; kh < Kh; kh++) {
                const int h_in = h_out * stride_h - pad_h + kh * dilation_h;
                if (h_in < 0 || h_in >= H_in) continue;

                for (int kw = 0; kw < Kw; kw++) {
                    const int w_in = w_out * stride_w - pad_w + kw * dilation_w;
                    if (w_in < 0 || w_in >= W_in) continue;

                    const int input_idx = ((n * C_in + c_in) * D_in + d_in) * H_in * W_in + h_in * W_in + w_in;
                    const int weight_idx = ((c_out * (C_in/groups) + (c_in - c_in_start)) * Kd + kd) * Kh * Kw + kh * Kw + kw;

                    sum += input[input_idx] * weight[weight_idx];
                }
            }
        }
    }
    output[idx] = sum;
}

torch::Tensor conv3d_forward(
    torch::Tensor input, torch::Tensor weight,
    int stride_d, int stride_h, int stride_w,
    int pad_d, int pad_h, int pad_w,
    int dilation_d, int dilation_h, int dilation_w,
    int groups, int C_out) {

    const auto N = input.size(0);
    const auto C_in = input.size(1);
    const auto D_in = input.size(2);
    const auto H_in = input.size(3);
    const auto W_in = input.size(4);

    const auto Kd = weight.size(2);
    const auto Kh = weight.size(3);
    const auto Kw = weight.size(4);

    const int D_out = (D_in + 2 * pad_d - dilation_d * (Kd - 1) - 1) / stride_d + 1;
    const int H_out = (H_in + 2 * pad_h - dilation_h * (Kh - 1) - 1) / stride_h + 1;
    const int W_out = (W_in + 2 * pad_w - dilation_w * (Kw - 1) - 1) / stride_w + 1;

    auto output = torch::zeros({N, C_out, D_out, H_out, W_out}, input.options());
    const int total_elements = N * C_out * D_out * H_out * W_out;

    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    hipLaunchKernelGGL(conv3d_kernel, dim3(num_blocks), dim3(block_size), 0, 0,
        input.data_ptr<float>(), weight.data_ptr<float>(), output.data_ptr<float>(),
        N, C_in, C_out,
        D_in, H_in, W_in,
        Kd, Kh, Kw,
        pad_d, pad_h, pad_w,
        stride_d, stride_h, stride_w,
        dilation_d, dilation_h, dilation_w,
        groups,
        D_out, H_out, W_out
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void custom_gemm_kernel(const float* x, const float* weight, const float* bias, float* out, int batch_size, int in_features, int out_features) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row < batch_size && col < out_features) {
        float sum = bias[col];
        for (int k = 0; k < in_features; ++k) {
            sum += x[row * in_features + k] * weight[col * in_features + k];
        }
        out[row * out_features + col] = sum;
    }
}

torch::Tensor custom_gemm_rocm(torch::Tensor x, torch::Tensor weight, torch::Tensor bias) {
    auto batch_size = x.size(0);
    auto in_features = x.size(1);
    auto out_features = weight.size(0);
    auto out = torch::zeros({batch_size, out_features}, x.options());

    dim3 block(16, 16);
    dim3 grid((out_features + block.x - 1) / block.x, (batch_size + block.y - 1) / block.y);

    hipLaunchKernelGGL(custom_gemm_kernel, grid, block, 0, 0, 
        x.data_ptr<float>(), weight.data_ptr<float>(), bias.data_ptr<float>(),
        out.data_ptr<float>(), batch_size, in_features, out_features
    );
    return out;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void maxpool_hardtanh_kernel(const float* input, float* output, int B, int C, int H, int W, int kH, int kW, int sH, int sW, float min_val, float max_val, int oH, int oW) {
    int b = blockIdx.z;
    int c = blockIdx.y;
    int h_out = blockIdx.x;
    int w_out = threadIdx.x;

    if (b >= B || c >= C || h_out >= oH || w_out >= oW) return;

    int start_h = h_out * sH;
    int start_w = w_out * sW;
    int end_h = min(start_h + kH, H);
    int end_w = min(start_w + kW, W);

    float max_val_region = -__FLT_MAX__;
    for (int h = start_h; h < end_h; ++h) {
        for (int w = start_w; w < end_w; ++w) {
            float val = input[b*C*H*W + c*H*W + h*W + w];
            if (val > max_val_region) max_val_region = val;
        }
    }

    max_val_region = fminf(max_val, fmaxf(min_val, max_val_region));
    output[b*C*oH*oW + c*oH*oW + h_out*oW + w_out] = max_val_region;
}

torch::Tensor maxpool_hardtanh_rocm(torch::Tensor x, int k, int s, float min_val, float max_val) {
    int B = x.size(0), C = x.size(1), H = x.size(2), W = x.size(3);
    int oH = (H - k)/s + 1;
    int oW = (W - k)/s + 1;
    auto output = torch::zeros({B, C, oH, oW}, x.options());

    dim3 blocks(oH, C, B);
    hipLaunchKernelGGL(maxpool_hardtanh_kernel, blocks, oW, 0, at::cuda::getCurrentHIPStream(), 
        x.data_ptr<float>(), output.data_ptr<float>(), B, C, H, W, k, k, s, s, min_val, max_val, oH, oW);

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>
#include <cfloat>

__global__ void scaled_min_kernel(const float* input, float* output, float scale_factor, int channels, int height, int width) {
    int batch = blockIdx.z;
    int w = blockIdx.x * blockDim.x + threadIdx.x;
    int h = blockIdx.y * blockDim.y + threadIdx.y;

    if (h >= height || w >= width) return;

    float min_val = FLT_MAX;
    for (int c = 0; c < channels; ++c) {
        int input_idx = batch * channels * height * width + c * height * width + h * width + w;
        float val = input[input_idx] * scale_factor;
        min_val = fminf(min_val, val);
    }

    int output_idx = batch * height * width + h * width + w;
    output[output_idx] = min_val;
}

torch::Tensor scaled_min_rocm(torch::Tensor input, float scale_factor) {
    TORCH_CHECK(input.dtype() == torch::kFloat32, "Input must be float32");
    TORCH_CHECK(input.is_contiguous(), "Input must be contiguous");
    TORCH_CHECK(input.dim() == 4, "Input must be 4D");

    int batch_size = input.size(0);
    int channels = input.size(1);
    int height = input.size(2);
    int width = input.size(3);

    auto output = torch::zeros({batch_size, 1, height, width}, input.options());

    dim3 block(16, 16);
    dim3 grid(
        (width + block.x - 1) / block.x,
        (height + block.y - 1) / block.y,
        batch_size
    );

    hipLaunchKernelGGL(scaled_min_kernel, grid, block, 0, 0, 
        input.data_ptr<float>(), output.data_ptr<float>(), scale_factor, channels, height, width);

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_maxpool_globalavg_clamp_kernel(const float* input, float* output,
                                                   int batch_size, int num_channels,
                                                   int input_depth, int input_height, int input_width,
                                                   int kernel_size,
                                                   float clamp_min, float clamp_max) {
    int batch_idx = blockIdx.x;
    int channel_idx = blockIdx.y;

    if (batch_idx >= batch_size || channel_idx >= num_channels) return;

    int output_depth = input_depth / kernel_size;
    int output_height = input_height / kernel_size;
    int output_width = input_width / kernel_size;
    int total_elements = output_depth * output_height * output_width;

    int input_offset = batch_idx * num_channels * input_depth * input_height * input_width
                       + channel_idx * input_depth * input_height * input_width;

    float sum = 0.0f;
    for (int d = 0; d < output_depth; ++d) {
        for (int h = 0; h < output_height; ++h) {
            for (int w = 0; w < output_width; ++w) {
                float max_val = -INFINITY;
                for (int kd = 0; kd < kernel_size; ++kd) {
                    for (int kh = 0; kh < kernel_size; ++kh) {
                        for (int kw = 0; kw < kernel_size; ++kw) {
                            int id = d * kernel_size + kd;
                            int ih = h * kernel_size + kh;
                            int iw = w * kernel_size + kw;
                            if (id >= input_depth || ih >= input_height || iw >= input_width) continue;
                            int idx = input_offset + id * (input_height * input_width)
                                                   + ih * input_width + iw;
                            float val = input[idx];
                            max_val = fmaxf(max_val, val);
                        }
                    }
                }
                sum += max_val;
            }
        }
    }
    float avg = sum / total_elements;
    avg = fminf(fmaxf(avg, clamp_min), clamp_max);
    int output_idx = batch_idx * num_channels * 1 * 1 * 1 + channel_idx * 1 * 1 * 1;
    output[output_idx] = avg;
}

torch::Tensor fused_maxpool_globalavg_clamp(torch::Tensor input, int kernel_size,
                                           float clamp_min, float clamp_max) {
    auto batch_size = input.size(0);
    auto num_channels = input.size(1);
    auto input_depth = input.size(2);
    auto input_height = input.size(3);
    auto input_width = input.size(4);

    auto output = torch::zeros({batch_size, num_channels, 1, 1, 1}, input.options());

    dim3 grid(batch_size, num_channels);
    hipLaunchKernelGGL(fused_maxpool_globalavg_clamp_kernel, grid, 1, 0, 0,
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        num_channels,
        input_depth,
        input_height,
        input_width,
        kernel_size,
        clamp_min,
        clamp_max);

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>

__global__ void masked_cumsum_kernel(const float* x, const bool* mask, float* out, int batch_size, int dim_size) {
    int batch_idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (batch_idx >= batch_size) return;

    const float* x_batch = x + batch_idx * dim_size;
    const bool* mask_batch = mask + batch_idx * dim_size;
    float* out_batch = out + batch_idx * dim_size;

    float cum_sum = 0.0f;
    for (int i = 0; i < dim_size; ++i) {
        if (mask_batch[i]) {
            cum_sum += x_batch[i];
        }
        out_batch[i] = cum_sum;
    }
}

torch::Tensor masked_cumsum_rocm(torch::Tensor x, torch::Tensor mask, int dim_size) {
    TORCH_CHECK(x.dim() == 2, "Expected 2D tensor (batch_size, dim_size)");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(mask.scalar_type() == torch::kBool, "mask must be bool");
    TORCH_CHECK(x.sizes() == mask.sizes(), "x and mask must be same size");

    auto x_cont = x.contiguous();
    auto mask_cont = mask.contiguous();
    auto out = torch::zeros_like(x_cont);

    int batch_size = x_cont.size(0);
    const int threads = 256;
    int blocks = (batch_size + threads - 1) / threads;

    hipLaunchKernelGGL(masked_cumsum_kernel, dim3(blocks), dim3(threads), 0, 0, 
        x_cont.data_ptr<float>(), 
        mask_cont.data_ptr<bool>(), 
        out.data_ptr<float>(), 
        batch_size,
        dim_size
    );

    return out;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <cfloat>

__global__ void maxpool2d_kernel(const float* input, float* output, int batch_size, int channels, int height, int width, int pooled_height, int pooled_width, int kernel_size, int stride, int padding, int dilation) {
    int ph = blockIdx.x * blockDim.x + threadIdx.x;
    int pw = blockIdx.y * blockDim.y + threadIdx.y;
    int c = blockIdx.z % channels;
    int n = blockIdx.z / channels;
    if (ph < pooled_height && pw < pooled_width) {
        float max_val = -FLT_MAX;
        for (int kh = 0; kh < kernel_size; ++kh) {
            for (int kw = 0; kw < kernel_size; ++kw) {
                int h = ph * stride - padding + kh * dilation;
                int w = pw * stride - padding + kw * dilation;
                if (h >= 0 && h < height && w >= 0 && w < width) {
                    int idx = ((n * channels + c) * height + h) * width + w;
                    float val = input[idx];
                    if (val > max_val) {
                        max_val = val;
                    }
                }
            }
        }
        int out_idx = ((n * channels + c) * pooled_height + ph) * pooled_width + pw;
        output[out_idx] = max_val;
    }
}

torch::Tensor maxpool2d_rocm(torch::Tensor input, int kernel_size, int stride, int padding, int dilation) {
    int batch_size = input.size(0);
    int channels = input.size(1);
    int height = input.size(2);
    int width = input.size(3);
    int pooled_height = (height + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;
    int pooled_width = (width + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;
    auto output = torch::zeros({batch_size, channels, pooled_height, pooled_width}, input.options());
    dim3 block(16, 16);
    dim3 grid((pooled_height + block.x - 1) / block.x, (pooled_width + block.y - 1) / block.y, batch_size * channels);
    hipLaunchKernelGGL(maxpool2d_kernel, grid, block, 0, 0, input.data_ptr<float>(), output.data_ptr<float>(), batch_size, channels, height, width, pooled_height, pooled_width, kernel_size, stride, padding, dilation);
    return output;
}

#include <torch/extension.h>
