__global__ void matrix_mul_kernel(const float* A, const float* B, float* C, int M, int N, int K) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row < M && col < N) {
        float sum = 0.0f;
        for (int k = 0; k < K; ++k) {
            sum += A[row * K + k] * B[k * N + col];
        }
        C[row * N + col] = sum;
    }
}

torch::Tensor matrix_mul_rocm(torch::Tensor A, torch::Tensor B) {
    int M = A.size(0);
    int N = B.size(1);
    int K = A.size(1);

    auto C = torch::zeros({M, N}, A.options());

    dim3 threads(16, 16);
    dim3 blocks((N + threads.x - 1) / threads.x, (M + threads.y - 1) / threads.y);

    matrix_mul_kernel<<<blocks, threads>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), M, N, K);

    return C;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void conv_transpose3d_kernel(
    const float* input, 
    const float* weight, 
    const float* bias, 
    float* output,
    int batch_size,
    int in_channels,
    int out_channels,
    int in_depth,
    int in_height,
    int in_width,
    int out_depth,
    int out_height,
    int out_width,
    int kernel_size,
    int stride,
    int padding,
    int dilation,
    int has_bias
) {
    int index = blockIdx.x * blockDim.x + threadIdx.x;
    int total_output_elements = batch_size * out_channels * out_depth * out_height * out_width;
    if (index >= total_output_elements) return;

    // Decompose index into 5D tensor indices
    int b = index / (out_channels * out_depth * out_height * out_width);
    int residual = index % (out_channels * out_depth * out_height * out_width);
    int oc = residual / (out_depth * out_height * out_width);
    residual %= (out_depth * out_height * out_width);
    int od = residual / (out_height * out_width);
    residual %= (out_height * out_width);
    int oh = residual / out_width;
    int ow = residual % out_width;

    float val = has_bias ? bias[oc] : 0.0f;

    for (int ic = 0; ic < in_channels; ++ic) {
        for (int kd = 0; kd < kernel_size; ++kd) {
            for (int kh = 0; kh < kernel_size; ++kh) {
                for (int kw = 0; kw < kernel_size; ++kw) {
                    int id = od + padding - kd * dilation;
                    if (id % stride != 0) continue;
                    id /= stride;
                    if (id < 0 || id >= in_depth) continue;

                    int ih = oh + padding - kh * dilation;
                    if (ih % stride != 0) continue;
                    ih /= stride;
                    if (ih < 0 || ih >= in_height) continue;

                    int iw = ow + padding - kw * dilation;
                    if (iw % stride != 0) continue;
                    iw /= stride;
                    if (iw < 0 || iw >= in_width) continue;

                    int input_idx = ((((b * in_channels + ic) * in_depth + id) * in_height + ih) * in_width + iw);
                    int weight_idx = ((((ic * out_channels + oc) * kernel_size + kd) * kernel_size + kh) * kernel_size + kw);

                    val += input[input_idx] * weight[weight_idx];
                }
            }
        }
    }
    output[index] = val;
}

torch::Tensor conv_transpose3d_rocm(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int kernel_size,
    int stride,
    int padding,
    int dilation,
    bool has_bias,
    int out_depth,
    int out_height,
    int out_width
) {
    auto batch_size = input.size(0);
    auto in_channels = input.size(1);
    auto out_channels = weight.size(1);

    auto output = torch::zeros({batch_size, out_channels, out_depth, out_height, out_width}, input.options());
    int total_elements = batch_size * out_channels * out_depth * out_height * out_width;
    int block_size = 256;
    int num_blocks = (total_elements + block_size - 1) / block_size;

    conv_transpose3d_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        has_bias ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        out_channels,
        input.size(2),
        input.size(3),
        input.size(4),
        out_depth,
        out_height,
        out_width,
        kernel_size,
        stride,
        padding,
        dilation,
        has_bias
    );
    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>

__global__ void fused_avg_pool_kernel(
    const float* input,
    float* output,
    int D_out,
    int H_out,
    int W_out,
    int D_in,
    int H_in,
    int W_in,
    int batch_size,
    int channels
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_out_elements = batch_size * channels * D_out * H_out * W_out;
    if (idx >= total_out_elements) return;

    int b = idx / (channels * D_out * H_out * W_out);
    int rem = idx % (channels * D_out * H_out * W_out);
    int c = rem / (D_out * H_out * W_out);
    rem = rem % (D_out * H_out * W_out);
    int d_out = rem / (H_out * W_out);
    rem = rem % (H_out * W_out);
    int h_out = rem / W_out;
    int w_out = rem % W_out;

    int d_start = d_out * 4;
    int d_end = d_start + 4;
    int h_start = h_out * 4;
    int h_end = h_start + 4;
    int w_start = w_out * 4;
    int w_end = w_start + 4;

    d_end = min(d_end, D_in);
    h_end = min(h_end, H_in);
    w_end = min(w_end, W_in);

    float sum = 0.0f;
    int count = 0;
    for (int d = d_start; d < d_end; ++d) {
        for (int h = h_start; h < h_end; ++h) {
            for (int w = w_start; w < w_end; ++w) {
                int input_idx = b * channels * D_in * H_in * W_in +
                                c * D_in * H_in * W_in +
                                d * H_in * W_in +
                                h * W_in +
                                w;
                sum += input[input_idx];
                count++;
            }
        }
    }

    output[idx] = count > 0 ? sum / count : 0.0f;
}

torch::Tensor fused_avg_pool_rocm(torch::Tensor input) {
    auto batch_size = input.size(0);
    auto channels = input.size(1);
    auto D_in = input.size(2);
    auto H_in = input.size(3);
    auto W_in = input.size(4);

    int D_out = D_in / 4;
    int H_out = H_in / 4;
    int W_out = W_in / 4;

    auto output = torch::zeros({batch_size, channels, D_out, H_out, W_out}, input.options());

    int total_elements = batch_size * channels * D_out * H_out * W_out;
    const int block_size = 256;
    int num_blocks = (total_elements + block_size - 1) / block_size;

    hipLaunchKernelGGL(
        fused_avg_pool_kernel,
        num_blocks, block_size, 0, 0,
        input.data_ptr<float>(), output.data_ptr<float>(),
        D_out, H_out, W_out, D_in, H_in, W_in,
        batch_size, channels
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_linear_sigmoid_kernel(const float* input, const float* weight, const float* bias, float* output, int input_size, int hidden_size, int batch_size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= batch_size * hidden_size) return;

    int row = idx / hidden_size;
    int col = idx % hidden_size;

    float sum = 0.0f;
    for(int k=0; k<input_size; k++) {
        sum += input[row*input_size + k] * weight[col*input_size + k];
    }
    sum += bias[col];
    output[idx] = 1.0f / (1.0f + expf(-sum));
}

torch::Tensor fused_linear_sigmoid_rocm(torch::Tensor input, torch::Tensor weight, torch::Tensor bias) {
    TORCH_CHECK(input.dim() == 2, "Input must be 2D");
    auto batch_size = input.size(0);
    auto input_size = input.size(1);
    auto hidden_size = weight.size(0);

    auto output = torch::empty({batch_size, hidden_size}, input.options());

    int total = batch_size * hidden_size;
    int block = 256;
    int grid = (total + block - 1) / block;

    hipLaunchKernelGGL(fused_linear_sigmoid_kernel, grid, block, 0, 0, 
        input.data_ptr<float>(), weight.data_ptr<float>(), bias.data_ptr<float>(),
        output.data_ptr<float>(), input_size, hidden_size, batch_size);

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void cumprod_kernel(const float* input, float* output, int dim_size, int batch_size) {
    extern __shared__ float s_data[];

    int batch_idx = blockIdx.x;
    if (batch_idx >= batch_size) return;

    int tid = threadIdx.x;

    int input_start = batch_idx * dim_size;
    for (int i = tid; i < dim_size; i += blockDim.x) {
        s_data[i] = input[input_start + i];
    }

    __syncthreads();

    for (int s = 1; s < dim_size; s *= 2) {
        for (int i = tid; i < dim_size; i += blockDim.x) {
            if (i >= s) {
                s_data[i] *= s_data[i - s];
            }
        }
        __syncthreads();
    }

    int output_start = batch_idx * dim_size;
    for (int i = tid; i < dim_size; i += blockDim.x) {
        output[output_start + i] = s_data[i];
    }
}

torch::Tensor cumprod_rocm(torch::Tensor input, int dim) {
    auto sizes = input.sizes();
    TORCH_CHECK(dim == 1 && sizes.size() == 2, "CUMPROD optimized for 2D tensors along dim=1");

    int batch_size = sizes[0];
    int dim_size = sizes[1];
    auto output = torch::empty_like(input);

    const int block_size = 256;
    size_t shared_size = dim_size * sizeof(float);

    hipLaunchKernelGGL(cumprod_kernel,
        dim3(batch_size), dim3(block_size), shared_size, 0,
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        dim_size,
        batch_size
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void sum_reduction_kernel(const float* input, float* output, int batch_size, int dim1, int dim2, int reduce_dim) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (reduce_dim == 1) {
        if (idx < batch_size * dim2) {
            int b = idx / dim2;
            int d2 = idx % dim2;
            float sum = 0.0f;
            for (int d1 = 0; d1 < dim1; ++d1) {
                sum += input[b * dim1 * dim2 + d1 * dim2 + d2];
            }
            output[b * dim2 + d2] = sum;
        }
    } else if (reduce_dim == 2) {
        if (idx < batch_size * dim1) {
            int b = idx / dim1;
            int d1 = idx % dim1;
            float sum = 0.0f;
            for (int d2 = 0; d2 < dim2; ++d2) {
                sum += input[b * dim1 * dim2 + d1 * dim2 + d2];
            }
            output[b * dim1 + d1] = sum;
        }
    }
}

torch::Tensor sum_reduction_rocm(torch::Tensor input, int reduce_dim) {
    int batch_size = input.size(0);
    int dim1 = input.size(1);
    int dim2 = input.size(2);
    auto output = reduce_dim == 1 ? torch::zeros({batch_size, 1, dim2}, input.options()) : torch::zeros({batch_size, dim1, 1}, input.options());

    const int block_size = 256;
    const int num_blocks = (batch_size * dim2 + block_size - 1) / block_size;

    sum_reduction_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), output.data_ptr<float>(), batch_size, dim1, dim2, reduce_dim);

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <math.h>

__global__ void fused_min_tanh_kernel(
    const float* input,
    float* output,
    int batch_size,
    int out_channels,
    int height,
    int width
) {
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int num_positions = batch_size * height * width;
    if (tid >= num_positions) return;

    int n = tid / (height * width);
    int remaining = tid % (height * width);
    int h = remaining / width;
    int w = remaining % width;

    int base = n * out_channels * height * width + h * width + w;
    float min_val = INFINITY;

    for (int c = 0; c < out_channels; ++c) {
        float val = input[base + c * height * width];
        min_val = fminf(min_val, val);
    }

    min_val = tanhf(min_val);
    min_val = tanhf(min_val);

    int output_idx = n * height * width + h * width + w;
    output[output_idx] = min_val;
}

torch::Tensor fused_min_tanh_rocm(torch::Tensor input) {
    auto contiguous_input = input.contiguous();
    auto batch_size = contiguous_input.size(0);
    int out_channels = contiguous_input.size(1);
    int height = contiguous_input.size(2);
    int width = contiguous_input.size(3);

    auto output = torch::zeros({batch_size, 1, height, width}, contiguous_input.options());

    int total_positions = batch_size * height * width;
    const int block_size = 256;
    int num_blocks = (total_positions + block_size - 1) / block_size;

    hipLaunchKernelGGL(
        fused_min_tanh_kernel,
        num_blocks,
        block_size,
        0,
        0,
        contiguous_input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        out_channels,
        height,
        width
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void max_reduction_kernel(const float* x, float* out, int dim, int outer_size, int inner_size) {
    int outer_idx = blockIdx.x * blockDim.x + threadIdx.x;
    int inner_idx = blockIdx.y * blockDim.y + threadIdx.y;

    if (outer_idx < outer_size && inner_idx < inner_size) {
        float max_val = x[outer_idx * inner_size * dim + inner_idx];
        for (int i = 1; i < dim; ++i) {
            float val = x[outer_idx * inner_size * dim + inner_idx + i * inner_size];
            if (val > max_val) {
                max_val = val;
            }
        }
        out[outer_idx * inner_size + inner_idx] = max_val;
    }
}

torch::Tensor max_reduction_rocm(torch::Tensor x, int dim) {
    auto sizes = x.sizes();
    int outer_size = 1;
    for (int i = 0; i < dim; ++i) {
        outer_size *= sizes[i];
    }
    int inner_size = 1;
    for (int i = dim + 1; i < sizes.size(); ++i) {
        inner_size *= sizes[i];
    }
    int reduction_dim_size = sizes[dim];

    auto out = torch::zeros({outer_size, inner_size}, x.options());

    dim3 block_size(16, 16);
    dim3 num_blocks((outer_size + block_size.x - 1) / block_size.x, (inner_size + block_size.y - 1) / block_size.y);

    max_reduction_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), out.data_ptr<float>(), reduction_dim_size, outer_size, inner_size);

    return out;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>

__global__ void fused_kernel(const float* x, float constant, const float* bias, float scale, float* out, 
                           int elements, int C, int H, int W) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < elements) {
        int c = (idx / (H * W)) % C;
        float val = min(x[idx], constant);
        val += bias[c];
        out[idx] = val * scale;
    }
}

torch::Tensor fused_min_add_mul(torch::Tensor x, float constant_val, torch::Tensor bias, float scaling) {
    auto out = torch::empty_like(x);
    int elements = x.numel();
    auto s = x.sizes();
    int C = s[1], H = s[2], W = s[3];

    hipLaunchKernelGGL(fused_kernel, 
        (elements+255)/256, 256, 0, 0,
        x.data_ptr<float>(), constant_val, bias.data_ptr<float>(), scaling,
        out.data_ptr<float>(), elements, C, H, W
    );

    return out;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void matrix_mult_kernel(const float* A, const float* B, float* C, int M, int N, int K) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row < M && col < N) {
        float sum = 0.0f;
        for (int i = 0; i < K; ++i) {
            sum += A[i * M + row] * B[col * K + i];
        }
        C[row * N + col] = sum;
    }
}

torch::Tensor matrix_mult_rocm(torch::Tensor A, torch::Tensor B, int M, int N, int K) {
    auto C = torch::zeros({M, N}, A.options());

    dim3 threads(16, 16);
    dim3 blocks((N + threads.x - 1) / threads.x, (M + threads.y - 1) / threads.y);

    hipLaunchKernelGGL(matrix_mult_kernel, blocks, threads, 0, 0, 
                       A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), M, N, K);

    return C;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>

__global__ void conv_transpose_1d_kernel(
    const float* input,
    const float* weight,
    float* output,
    int batch_size,
    int in_channels,
    int out_channels,
    int input_length,
    int kernel_size,
    int stride,
    int padding,
    int dilation,
    int output_length
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_output_elements = batch_size * out_channels * output_length;
    if (idx >= total_output_elements) return;

    int batch = idx / (out_channels * output_length);
    int residual = idx % (out_channels * output_length);
    int out_c = residual / output_length;
    int output_pos = residual % output_length;

    const float* input_ptr = input + batch * in_channels * input_length;

    float val = 0.0f;
    for (int in_c = 0; in_c < in_channels; ++in_c) {
        for (int k = 0; k < kernel_size; ++k) {
            int effective_k = k * dilation;
            int jv = output_pos + padding - effective_k;
            if (jv < 0 || (jv % stride) != 0) continue;

            int j = jv / stride;
            if (j >= input_length) continue;

            float input_val = input_ptr[in_c * input_length + j];
            int weight_idx = in_c * out_channels * kernel_size + out_c * kernel_size + k;
            val += input_val * weight[weight_idx];
        }
    }
    output[idx] = val;
}

torch::Tensor conv_transpose_1d_rocm(torch::Tensor input, torch::Tensor weight, int kernel_size, int stride, int padding, int dilation) {
    input = input.contiguous();
    weight = weight.contiguous();

    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int input_length = input.size(2);
    int out_channels = weight.size(1);

    int output_length = (input_length - 1) * stride - 2 * padding + dilation * (kernel_size - 1) + 1;

    auto output = torch::zeros({batch_size, out_channels, output_length}, input.options());

    const int block_size = 256;
    int num_elements = batch_size * out_channels * output_length;
    int num_blocks = (num_elements + block_size - 1) / block_size;

    hipLaunchKernelGGL(conv_transpose_1d_kernel, num_blocks, block_size, 0, 0,
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        out_channels,
        input_length,
        kernel_size,
        stride,
        padding,
        dilation,
        output_length
    );
    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_min_clamp_dropout_kernel(const float* x, float* out, float min_val, float max_val, 
float dropout_p, bool training, int size, float inv_dropout, int seed) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        unsigned int rand = (seed + idx) * 1103515245 + 12345;
        float mask = (rand / 4294967296.0f) > dropout_p ? 1.0f : 0.0f;

        float val = x[idx];
        val = fminf(val, min_val);
        val = fmaxf(fminf(val, max_val), min_val);

        if (training) {
            val = mask * val * inv_dropout;
        }
        out[idx] = val;
    }
}

torch::Tensor fused_min_clamp_dropout_rocm(torch::Tensor x, float min_val, float max_val, float dropout_p, bool training) {
    auto out = torch::empty_like(x);
    int size = x.numel();
    const int block_size = 256;
    int grid_size = (size + block_size - 1) / block_size;
    int seed = torch::randint(1e8, {}, x.options().dtype(torch::kInt)).item<int>();
    float inv_dropout = 1.0f / (1.0f - dropout_p);

    hipLaunchKernelGGL(fused_min_clamp_dropout_kernel, 
        dim3(grid_size), dim3(block_size), 0, at::hip::getCurrentHIPStream(), 
        x.data_ptr<float>(), out.data_ptr<float>(), min_val, max_val, 
        dropout_p, training, size, inv_dropout, seed
    );
    return out;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void l2_norm_kernel(const float* x, float* out, int num_elements, int dim) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < num_elements) {
        int batch_idx = idx / dim;
        int element_idx = idx % dim;
        float sum = 0.0f;
        for (int i = 0; i < dim; ++i) {
            sum += x[batch_idx * dim + i] * x[batch_idx * dim + i];
        }
        out[idx] = x[idx] / sqrt(sum);
    }
}

torch::Tensor l2_norm_rocm(torch::Tensor x) {
    auto num_elements = x.numel();
    auto out = torch::zeros_like(x);
    int dim = x.size(1);

    const int block_size = 256;
    const int num_blocks = (num_elements + block_size - 1) / block_size;

    l2_norm_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), out.data_ptr<float>(), num_elements, dim);

    return out;
}

