__global__ void fused_gelu_pool_kernel(const float* input, float* output, int H, int W, int B, int C) {
    int batch = blockIdx.x;
    int channel = blockIdx.y;

    if (batch >= B || channel >= C) return;

    extern __shared__ float shared[];

    int num_elements = H * W;
    int start_offset = batch * C * H * W + channel * H * W;

    float thread_sum = 0.0f;
    for (int idx = threadIdx.x; idx < num_elements; idx += blockDim.x) {
        float x_val = input[start_offset + idx];
        const float sqrt_2_over_pi = 0.7978845608028654f;
        const float coff = 0.044715f;
        float x_cubed = x_val * x_val * x_val;
        float inner = sqrt_2_over_pi * (x_val + coff * x_cubed);
        float gelu = 0.5f * x_val * (1.0f + tanhf(inner));
        thread_sum += gelu;
    }

    shared[threadIdx.x] = thread_sum;
    __syncthreads();

    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            shared[threadIdx.x] += shared[threadIdx.x + stride];
        }
        __syncthreads();
    }

    if (threadIdx.x == 0) {
        output[batch * C + channel] = shared[0] / num_elements;
    }
}

torch::Tensor fused_gelu_pool_rocm(torch::Tensor input) {
    TORCH_CHECK(input.dim() == 4, "Input must be 4D");
    TORCH_CHECK(input.is_cuda(), "Input must be a CUDA tensor");

    auto contiguous_input = input.contiguous();
    int B = contiguous_input.size(0);
    int C = contiguous_input.size(1);
    int H = contiguous_input.size(2);
    int W = contiguous_input.size(3);

    auto output = torch::zeros({B, C}, contiguous_input.options());

    int block_size = 256;
    dim3 grid(B, C);
    size_t shared_mem = block_size * sizeof(float);

    hipLaunchKernelGGL(fused_gelu_pool_kernel, grid, block_size, shared_mem, 0,
        contiguous_input.data_ptr<float>(), output.data_ptr<float>(), H, W, B, C);
    HIP_CHECK(hipGetLastError());
    HIP_CHECK(hipDeviceSynchronize());

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void softmax_kernel(const float* input, float* output, int batch_size, int num_features) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < batch_size) {
        float max_val = input[idx * num_features];
        for (int i = 1; i < num_features; ++i) {
            if (input[idx * num_features + i] > max_val) {
                max_val = input[idx * num_features + i];
            }
        }

        float sum = 0.0f;
        for (int i = 0; i < num_features; ++i) {
            sum += expf(input[idx * num_features + i] - max_val);
        }

        for (int i = 0; i < num_features; ++i) {
            output[idx * num_features + i] = expf(input[idx * num_features + i] - max_val) / sum;
        }
    }
}

torch::Tensor softmax_rocm(torch::Tensor input) {
    int batch_size = input.size(0);
    int num_features = input.size(1);
    auto output = torch::zeros_like(input);

    const int block_size = 256;
    const int num_blocks = (batch_size + block_size - 1) / block_size;

    softmax_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), output.data_ptr<float>(), batch_size, num_features);

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <math.h>

__global__ void fused_act_add_kernel(const float* x_norm, const float* x_conv, float* output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = x_norm[idx];
        val = tanhf(val);
        float relu_val = fminf(fmaxf(val + 3, 0.0f), 6.0f);
        val = val * relu_val / 6.0f;
        output[idx] = x_conv[idx] + val;
    }
}

torch::Tensor fused_act_add_rocm(torch::Tensor x_norm, torch::Tensor x_conv) {
    auto size = x_norm.numel();
    TORCH_CHECK(size == x_conv.numel(), "Tensors must have the same size");
    auto output = torch::empty_like(x_conv);

    int block_size = 256;
    int num_blocks = (size + block_size - 1) / block_size;

    hipLaunchKernelGGL(fused_act_add_kernel, dim3(num_blocks), dim3(block_size), 0, 0, 
        x_norm.contiguous().data_ptr<float>(), x_conv.contiguous().data_ptr<float>(), output.data_ptr<float>(), size);

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
